package org.wikipedia.util

import org.json.JSONArray
import org.json.JSONObject

/** Reads a string entry, returning `null` when the key is absent or JSON `null`. */
fun JSONObject.stringOrNull(key: String): String? =
    if (has(key) && !isNull(key)) optString(key) else null

fun JSONObject.stringOr(key: String, fallback: String): String = stringOrNull(key) ?: fallback

fun JSONObject.booleanOrNull(key: String): Boolean? =
    if (has(key) && !isNull(key)) optBoolean(key) else null

fun JSONObject.booleanOr(key: String, fallback: Boolean): Boolean = booleanOrNull(key) ?: fallback

fun JSONObject.intOr(key: String, fallback: Int): Int = if (has(key) && !isNull(key)) optInt(key, fallback) else fallback

fun JSONObject.longOr(key: String, fallback: Long): Long = if (has(key) && !isNull(key)) optLong(key, fallback) else fallback

fun JSONObject.objectOrNull(key: String): JSONObject? =
    if (has(key) && !isNull(key)) optJSONObject(key) else null

fun JSONObject.arrayOrNull(key: String): JSONArray? =
    if (has(key) && !isNull(key)) optJSONArray(key) else null

fun JSONObject.stringList(key: String): List<String> {
    val array = arrayOrNull(key) ?: return emptyList()
    return (0 until array.length()).mapNotNull { index ->
        val value = array.opt(index)
        if (value == null || value === JSONObject.NULL) null else value.toString()
    }
}

fun JSONObject.objectList(key: String): List<JSONObject> {
    val array = arrayOrNull(key) ?: return emptyList()
    return (0 until array.length()).mapNotNull { index -> array.optJSONObject(index) }
}

/** Builds a [JSONObject] from pairs, dropping entries whose value is `null`. */
fun jsonOf(vararg pairs: Pair<String, Any?>): JSONObject {
    val json = JSONObject()
    pairs.forEach { (key, value) -> if (value != null) json.put(key, value) }
    return json
}

fun jsonArrayOf(values: Collection<Any?>): JSONArray {
    val array = JSONArray()
    values.forEach { array.put(it ?: JSONObject.NULL) }
    return array
}

package org.wikipedia.page

import org.wikipedia.util.jsonOf
import org.wikipedia.util.stringOr
import org.wikipedia.util.stringOrNull
import org.json.JSONObject

/**
 * Logical identity of a wiki article.
 *
 * An article is identified by the pair of its wiki language and its API title. That pair - not
 * the number of reading lists it lives in, not its display title, and not the database row id
 * that happens to carry the membership - is what makes two rows the *same* logical article.
 */
data class PageTitle(
    val languageCode: String,
    val apiTitle: String,
    val displayTitle: String = apiTitle.replace('_', ' ')
) {
    /** Stable key used for grouping and de-duplication: `languageCode:apiTitle`. */
    val logicalKey: String get() = key(languageCode, apiTitle)

    override fun toString(): String = logicalKey

    fun toJson(): JSONObject = jsonOf(
        "language" to languageCode,
        "apiTitle" to apiTitle,
        "displayTitle" to displayTitle
    )

    companion object {
        const val DEFAULT_LANGUAGE = "en"

        fun key(languageCode: String, apiTitle: String): String = "$languageCode:$apiTitle"

        /** Parses the canonical `language:Api_Title` key used across storage and IPC. */
        fun fromKey(key: String): PageTitle {
            val separator = key.indexOf(':')
            if (separator <= 0 || separator == key.length - 1) {
                return PageTitle(DEFAULT_LANGUAGE, key.replace(' ', '_'))
            }
            return PageTitle(key.substring(0, separator), key.substring(separator + 1))
        }

        fun fromJson(json: JSONObject): PageTitle = PageTitle(
            languageCode = json.stringOr("language", DEFAULT_LANGUAGE),
            apiTitle = json.stringOr("apiTitle", ""),
            displayTitle = json.stringOrNull("displayTitle")
                ?: json.stringOr("apiTitle", "").replace('_', ' ')
        )
    }
}

package org.wikipedia.database

import java.util.concurrent.CopyOnWriteArrayList

fun interface ChangeListener<T> {
    fun onChanged(value: T)
}

/** Handle returned by [QueryFlow.observe]; cancelling detaches the listener. */
class Subscription internal constructor(private val onCancel: () -> Unit) {
    private var cancelled = false

    fun cancel() {
        if (!cancelled) {
            cancelled = true
            onCancel()
        }
    }
}

/**
 * Push-based projection of a database query.
 *
 * Surfaces subscribe once and receive a fresh projection whenever the backing tables change, so
 * a page never has to be rebuilt by hand after a write. The projection is recomputed lazily from
 * the source lambda and only published when it actually differs from the last published value.
 */
class QueryFlow<T>(private val source: () -> T) {
    private val listeners = CopyOnWriteArrayList<ChangeListener<T>>()
    private var cached: T = source()

    val value: T get() = cached

    fun observe(listener: ChangeListener<T>): Subscription {
        listeners.add(listener)
        listener.onChanged(cached)
        return Subscription { listeners.remove(listener) }
    }

    fun invalidate() {
        val next = source()
        if (next == cached) {
            return
        }
        cached = next
        listeners.forEach { it.onChanged(cached) }
    }

    fun close() {
        listeners.clear()
    }
}

package org.wikipedia.database

import android.content.SharedPreferences

/**
 * Small durable key/value seam used by the Saved stack so that sort modes, the sync preference
 * and the reading list tables survive process death. [SharedPreferencesKeyValueStore] is the
 * production implementation backed by the platform preferences file.
 */
interface KeyValueStore {
    fun getString(key: String): String?

    fun putString(key: String, value: String)

    fun getBoolean(key: String, fallback: Boolean): Boolean

    fun putBoolean(key: String, value: Boolean)
}

class SharedPreferencesKeyValueStore(private val preferences: SharedPreferences?) : KeyValueStore {
    override fun getString(key: String): String? = preferences?.getString(key, null)

    override fun putString(key: String, value: String) {
        preferences?.edit()?.putString(key, value)?.apply()
    }

    override fun getBoolean(key: String, fallback: Boolean): Boolean =
        preferences?.getBoolean(key, fallback) ?: fallback

    override fun putBoolean(key: String, value: Boolean) {
        preferences?.edit()?.putBoolean(key, value)?.apply()
    }
}

/** In-memory store used when no preferences file is attached (for example in isolated tooling). */
class InMemoryKeyValueStore : KeyValueStore {
    private val values = HashMap<String, Any?>()

    override fun getString(key: String): String? = values[key] as? String

    override fun putString(key: String, value: String) {
        values[key] = value
    }

    override fun getBoolean(key: String, fallback: Boolean): Boolean = values[key] as? Boolean ?: fallback

    override fun putBoolean(key: String, value: Boolean) {
        values[key] = value
    }
}

package org.wikipedia.util

/** Ordered record of the production entry points that a transition actually executed. */
interface ProductionLog {
    fun record(method: String)
}

/** In-memory [ProductionLog]; the sequence is what an external observer inspects. */
class RecordingProductionLog : ProductionLog {
    private val methods = mutableListOf<String>()

    val invocations: List<String> get() = methods.toList()

    override fun record(method: String) {
        methods.add(method)
    }

    fun clear() {
        methods.clear()
    }
}

/** Wraps a list so that production code can contribute to an externally owned record. */
class ListBackedProductionLog(private val sink: MutableList<String>) : ProductionLog {
    override fun record(method: String) {
        sink.add(method)
    }
}

class CompositeProductionLog(private val delegates: List<ProductionLog>) : ProductionLog {
    override fun record(method: String) {
        delegates.forEach { it.record(method) }
    }
}

package org.wikipedia.auth

import org.wikipedia.database.QueryFlow

/**
 * The signed-in account as the Saved stack needs it.
 *
 * [isTemporaryAccount] marks a throw-away account; such an account is signed in but is *not*
 * eligible for reading list synchronization, so a pull-to-refresh from one prompts for login
 * instead of dispatching a sync.
 */
data class AccountInfo(
    val isLoggedIn: Boolean = false,
    val isTemporaryAccount: Boolean = false,
    val userName: String? = null
) {
    val isEligibleForSync: Boolean get() = isLoggedIn && !isTemporaryAccount
}

class AccountStateHolder(initial: AccountInfo = AccountInfo()) {
    private var current = initial
    private val flow = QueryFlow { current }

    val account: AccountInfo get() = current

    fun observe() = flow

    fun onLogin(userName: String?, temporary: Boolean = false) {
        current = AccountInfo(isLoggedIn = true, isTemporaryAccount = temporary, userName = userName)
        flow.invalidate()
    }

    fun onLogout() {
        current = AccountInfo()
        flow.invalidate()
    }

    fun update(account: AccountInfo) {
        if (account != current) {
            current = account
            flow.invalidate()
        }
    }
}

package org.wikipedia.database

import org.wikipedia.readinglist.ReadList
import org.wikipedia.readinglist.ReadingListPage
import org.wikipedia.readinglist.ReadingListWithPages
import org.wikipedia.util.jsonArrayOf
import org.wikipedia.util.jsonOf
import org.wikipedia.util.objectList
import org.json.JSONObject

/**
 * Application-owned persistence for the Saved experience.
 *
 * Two tables: collections (`ReadList`) and memberships (`ReadingListPage`). Reads are exposed as
 * [QueryFlow] projections so that every surface watching saved content is re-projected after a
 * write instead of being rebuilt by hand. Writes bump a change counter and re-publish the
 * projections, and are mirrored into the [KeyValueStore] so state survives process death.
 */
class AppDatabase(private val store: KeyValueStore? = null) {

    private val lists = LinkedHashMap<Long, ReadList>()
    private val pages = LinkedHashMap<Long, ReadingListPage>()
    private var nextListId = 1L
    private var nextPageId = 1L

    private val listsFlow = QueryFlow { lists.values.toList() }
    private val withPagesFlow = QueryFlow { loadReadingListsWithPages() }

    init {
        restore()
    }

    // ---------------------------------------------------------------- collections

    fun insertList(list: ReadList): Long {
        val id = if (list.id > 0) list.id else nextListId
        val stored = list.copy(id = id)
        lists[id] = stored
        if (id >= nextListId) {
            nextListId = id + 1
        }
        invalidate()
        return id
    }

    fun updateList(list: ReadList) {
        if (lists.containsKey(list.id)) {
            lists[list.id] = list
            invalidate()
        }
    }

    fun deleteList(list: ReadList) {
        lists.remove(list.id)
        pages.values.filter { it.listId == list.id }.forEach { pages.remove(it.id) }
        invalidate()
    }

    fun getList(id: Long): ReadList? = lists[id]

    fun getListByTitle(title: String): ReadList? =
        lists.values.firstOrNull { !it.isDeleted && it.title.equals(title, ignoreCase = true) }

    fun getLists(): List<ReadList> = lists.values.filter { !it.isDeleted }

    fun observeLists(): QueryFlow<List<ReadList>> = listsFlow

    // ---------------------------------------------------------------- memberships

    fun insertPage(page: ReadingListPage): Long {
        val id = if (page.id > 0) page.id else nextPageId
        val stored = page.copy(id = id)
        pages[id] = stored
        if (id >= nextPageId) {
            nextPageId = id + 1
        }
        invalidate()
        return id
    }

    fun updatePage(page: ReadingListPage) {
        if (pages.containsKey(page.id)) {
            pages[page.id] = page
            invalidate()
        }
    }

    fun deletePage(page: ReadingListPage) {
        pages.remove(page.id)
        invalidate()
    }

    fun deletePages(predicate: (ReadingListPage) -> Boolean): Int {
        val doomed = pages.values.filter(predicate)
        doomed.forEach { pages.remove(it.id) }
        if (doomed.isNotEmpty()) {
            invalidate()
        }
        return doomed.size
    }

    fun getPage(listId: Long, articleKey: String): ReadingListPage? =
        pages.values.firstOrNull { it.listId == listId && it.title.logicalKey == articleKey }

    fun getPages(listId: Long): List<ReadingListPage> =
        pages.values.filter { it.listId == listId }.toList()

    fun getAllPages(): List<ReadingListPage> = pages.values.toList()

    // ---------------------------------------------------------------- projections

    /** Collections joined with their active articles; queued-for-delete rows are excluded. */
    fun loadReadingListsWithPages(): List<ReadingListWithPages> =
        lists.values.filter { !it.isDeleted }.map { ReadingListWithPages.project(it, pages.values.toList()) }

    fun observeReadingListsWithPages(): QueryFlow<List<ReadingListWithPages>> = withPagesFlow

    fun invalidate() {
        listsFlow.invalidate()
        withPagesFlow.invalidate()
        persist()
    }

    // ---------------------------------------------------------------- durability

    private fun persist() {
        val target = store ?: return
        target.putString(KEY_LISTS, jsonArrayOf(lists.values.map { it.toJson() }).toString())
        target.putString(KEY_PAGES, jsonArrayOf(pages.values.map { it.toJson() }).toString())
    }

    private fun restore() {
        val target = store ?: return
        val storedLists = target.getString(KEY_LISTS)?.let { runCatching { JSONObject(it) }.getOrNull() }
        val storedPages = target.getString(KEY_PAGES)?.let { runCatching { JSONObject(it) }.getOrNull() }
        if (storedLists == null && storedPages == null) {
            return
        }
        storedLists?.let { json ->
            json.objectList("rows").forEach { raw ->
                val list = ReadList.fromJson(raw)
                lists[list.id] = list
                if (list.id >= nextListId) {
                    nextListId = list.id + 1
                }
            }
        }
        storedPages?.let { json ->
            json.objectList("rows").forEach { raw ->
                val page = ReadingListPage.fromJson(raw)
                pages[page.id] = page
                if (page.id >= nextPageId) {
                    nextPageId = page.id + 1
                }
            }
        }
        invalidate()
    }

    /** Compact snapshot of the tables; used by diagnostics and by tooling. */
    fun debugSnapshot(): JSONObject = jsonOf(
        "collections" to jsonArrayOf(lists.values.map { it.toJson() }),
        "memberships" to jsonArrayOf(pages.values.map { it.toJson() })
    )

    companion object {
        private const val KEY_LISTS = "reading_list_collections"
        private const val KEY_PAGES = "reading_list_memberships"
    }
}

