package org.wikipedia.offline

import org.wikipedia.page.PageTitle
import org.wikipedia.database.QueryFlow
import org.wikipedia.database.QueryFlow as Flow
import org.wikipedia.util.ProductionLog

/** How completely an article is available for offline reading right now. */
enum class ArticleOfflineStatus {
    NOT_DOWNLOADED,
    DOWNLOADING,
    AVAILABLE,
    STALE
}

data class ArticleAvailability(
    val status: ArticleOfflineStatus = ArticleOfflineStatus.NOT_DOWNLOADED,
    val downloadProgress: Int = NO_ACTIVE_DOWNLOAD
) {
    val hasActiveDownload: Boolean get() = status == ArticleOfflineStatus.DOWNLOADING

    companion object {
        const val NO_ACTIVE_DOWNLOAD = -1
    }
}

/**
 * Application-owned view of offline availability for saved articles.
 *
 * Rows of the Saved surfaces join this store so a visible article always reports whether it is
 * available offline and whether a download is still running. Downloads are outside the Saved
 * feature; this store only mirrors their observable outcome.
 */
class ArticleOfflineStore(private val log: ProductionLog? = null) {
    private val availability = LinkedHashMap<String, ArticleAvailability>()
    private val flow: QueryFlow<Map<String, ArticleAvailability>> = QueryFlow { LinkedHashMap(availability) }

    fun observe(): QueryFlow<Map<String, ArticleAvailability>> = flow

    fun availabilityFor(title: PageTitle): ArticleAvailability =
        availability[title.logicalKey] ?: ArticleAvailability()

    fun setStatus(title: PageTitle, status: ArticleOfflineStatus, progress: Int = ArticleAvailability.NO_ACTIVE_DOWNLOAD) {
        log?.record("ArticleOfflineStore.setStatus:${title.logicalKey}:$status")
        availability[title.logicalKey] = ArticleAvailability(status, progress)
        flow.invalidate()
    }

    fun beginDownload(title: PageTitle, progress: Int) =
        setStatus(title, ArticleOfflineStatus.DOWNLOADING, progress)

    fun reportProgress(title: PageTitle, progress: Int) {
        log?.record("ArticleOfflineStore.reportProgress:${title.logicalKey}:$progress")
        availability[title.logicalKey] = ArticleAvailability(ArticleOfflineStatus.DOWNLOADING, progress)
        flow.invalidate()
    }

    fun completeDownload(title: PageTitle) {
        setStatus(title, ArticleOfflineStatus.AVAILABLE, 100)
    }
}

package org.wikipedia.dataclients

import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog
import java.io.IOException

/** Page metadata as returned by the wiki API. */
data class PageMetadata(
    val languageCode: String,
    val apiTitle: String,
    val displayTitle: String
)

/**
 * External HTTP boundary.
 *
 * Everything above this interface is application-owned; everything below it is a leaf. The
 * production app supplies a wiki-API backed implementation. A `null` service means no network is
 * reachable, which is what the offline path looks like from the caller's point of view.
 */
interface WikiService {
    @Throws(IOException::class)
    fun getPageMetadata(languageCode: String, apiTitle: String): PageMetadata
}

/**
 * Resolves the canonical identity of an article before it is persisted.
 *
 * Saving must never depend on the network being available. If the metadata request cannot be
 * served - the device is offline or the request fails - the original language and API title are
 * used unchanged, so the persisted identity is always the one the reader acted on.
 */
class RedirectResolver(
    private val service: WikiService?,
    private val log: ProductionLog? = null
) {
    fun resolve(title: PageTitle): PageTitle {
        val client = service
        if (client == null) {
            log?.record("RedirectResolver.resolve:offline")
            return title
        }
        return try {
            val metadata = client.getPageMetadata(title.languageCode, title.apiTitle)
            log?.record("RedirectResolver.resolve:resolved")
            PageTitle(metadata.languageCode, metadata.apiTitle, metadata.displayTitle)
        } catch (e: IOException) {
            log?.record("RedirectResolver.resolve:io_failure")
            title
        } catch (e: WikiApiException) {
            log?.record("RedirectResolver.resolve:api_failure")
            title
        }
    }
}

/** Non-I/O failure reported by the wiki API; also handled by falling back to the original title. */
class WikiApiException(message: String, cause: Throwable? = null) : RuntimeException(message, cause)

package org.wikipedia.readinglist

import android.os.Handler
import android.os.Looper

/** Handle for a task queued on a [SavedScheduler]. */
interface ScheduledTask {
    fun cancel()
}

/**
 * Timing seam used for the search debounce and for anything else the Saved surface defers.
 *
 * Production posts onto the main looper; a caller that needs deterministic ordering can drive a
 * scheduler it controls instead, which is how the debounce window is exercised exactly.
 */
interface SavedScheduler {
    fun postDelayed(delayMillis: Long, task: Runnable): ScheduledTask

    companion object {
        /** Search input is only applied once the reader stops typing for this long. */
        const val SEARCH_DEBOUNCE_DELAY_MS = 150L

        fun mainThread(): SavedScheduler = MainThreadSavedScheduler()

        fun manual(): ManualSavedScheduler = ManualSavedScheduler()
    }
}

class MainThreadSavedScheduler : SavedScheduler {
    private var handler: Handler? = null

    private fun handler(): Handler {
        val existing = handler
        if (existing != null) {
            return existing
        }
        val created = Handler(Looper.getMainLooper())
        handler = created
        return created
    }

    override fun postDelayed(delayMillis: Long, task: Runnable): ScheduledTask {
        val target = handler()
        target.postDelayed(task, delayMillis)
        return object : ScheduledTask {
            override fun cancel() {
                target.removeCallbacks(task)
            }
        }
    }
}

/** Scheduler whose clock only moves when the caller advances it. */
class ManualSavedScheduler : SavedScheduler {
    private var now = 0L
    private val pending = mutableListOf<Pending>()

    private data class Pending(val dueAt: Long, val task: Runnable, var cancelled: Boolean)

    val nowMillis: Long get() = now

    val pendingCount: Int get() = pending.count { !it.cancelled }

    override fun postDelayed(delayMillis: Long, task: Runnable): ScheduledTask {
        val entry = Pending(now + delayMillis, task, false)
        pending.add(entry)
        return object : ScheduledTask {
            override fun cancel() {
                entry.cancelled = true
            }
        }
    }

    /** Moves the clock forward and runs everything that has come due, in due order. */
    fun advanceBy(millis: Long) {
        now += millis
        runDueTasks()
    }

    fun runDueTasks() {
        while (true) {
            val due = pending.filter { !it.cancelled && it.dueAt <= now }.minByOrNull { it.dueAt }
                ?: break
            pending.remove(due)
            due.task.run()
        }
        pending.removeAll { it.cancelled }
    }
}

package org.wikipedia.readinglist

import org.wikipedia.offline.ArticleAvailability
import org.wikipedia.offline.ArticleOfflineStatus
import org.wikipedia.page.PageTitle
import org.wikipedia.util.jsonArrayOf
import org.wikipedia.util.jsonOf
import org.json.JSONObject

/** The two top level views of the Saved experience. */
enum class SavedTab {
    ALL_ARTICLES,
    COLLECTIONS;

    companion object {
        fun parse(value: String?): SavedTab? = entries.firstOrNull {
            it.name.equals(value, ignoreCase = true) || it.name.equals(value?.replace("-", "_"), ignoreCase = true)
        }
    }
}

/**
 * Narrowing available on the All articles tab.
 *
 * [NOT_IN_COLLECTION] keeps only articles whose *complete* set of containing collections is the
 * default collection - an article that is also in any user-created collection is excluded, even
 * when it is also in Saved.
 */
enum class ArticleFilter {
    ALL_ARTICLES,
    NOT_IN_COLLECTION;

    companion object {
        fun parse(value: String?): ArticleFilter? = entries.firstOrNull { it.name.equals(value, ignoreCase = true) }
    }
}

/**
 * Sort choices offered per view. Ordinals are persisted, so the numbering is part of the
 * durable format: name ascending is 0 and name descending is 1.
 */
enum class ReadingListSortMode(val preferenceKey: String) {
    SORT_BY_NAME_ASC("sort_by_name_asc"),
    SORT_BY_NAME_DESC("sort_by_name_desc"),
    SORT_BY_NEWEST_FIRST("sort_by_newest_first"),
    SORT_BY_OLDEST_FIRST("sort_by_oldest_first");

    companion object {
        fun parse(value: String?): ReadingListSortMode? = entries.firstOrNull { it.name.equals(value, ignoreCase = true) }

        fun fromOrdinal(value: Int): ReadingListSortMode = entries.getOrElse(value) { SORT_BY_NAME_ASC }
    }
}

/** Actions the overflow menu offers; they differ per tab because the row types differ. */
enum class SavedMenuAction {
    SORT,
    FILTER,
    SELECT_ALL,
    DELETE,
    NEW_COLLECTION
}

enum class SavedRecoveryAction {
    NONE,
    CLEAR_SEARCH,
    START_SYNC,
    LOG_IN,
    CREATE_COLLECTION
}

/** Why the current view shows nothing. Loading is deliberately distinct from empty. */
sealed class SavedEmptyState {
    object NONE : SavedEmptyState()
    object LOADING : SavedEmptyState()
    data class SEARCH_NO_RESULTS(val query: String) : SavedEmptyState()
    object NO_SAVED_ARTICLES : SavedEmptyState()
    object NO_COLLECTIONS : SavedEmptyState()
}

/** Prompt shown alongside the rows; driven by login, sync preference and shared-list receipt. */
enum class SavedOnboardingState {
    NONE,
    LOGIN_PROMPT,
    SYNC_REMINDER,
    SHARED_COLLECTION_RECEIVED;

    companion object {
        fun parse(value: String?): SavedOnboardingState? = entries.firstOrNull {
            it.name.equals(value, ignoreCase = true) ||
                it.name.replace("_", "").equals(value?.replace(" ", "").replace("_", ""), ignoreCase = true)
        }
    }
}

/** Transient feedback the surface shows after an action. */
enum class SavedFeedback {
    NONE,
    SYNCED,
    SYNC_FAILED,
    LOGIN_REQUIRED,
    LIMIT_REACHED,
    ARTICLE_SAVED,
    ARTICLE_UNSAVED,
    COLLECTION_CREATED,
    COLLECTION_DELETED,
    ARTICLES_DELETED,
    COLLECTIONS_DELETED,
    RESTORED,
    NOTHING_SELECTED,
    COLLECTION_UNAVAILABLE
}

/**
 * One row of the All articles tab.
 *
 * An article that lives in several collections still produces exactly one row; [collectionTitles]
 * retains every collection it belongs to and [id] is the single membership row id used for
 * selection, so a logical article can never be selected twice.
 */
data class SavedArticleRow(
    val id: Long,
    val title: PageTitle,
    val collectionTitles: List<String>,
    val isInDefaultCollection: Boolean,
    val offlineStatus: ArticleOfflineStatus,
    val downloadProgress: Int
) {
    /** True when the article belongs to at least one user-created collection. */
    val isInUserCollection: Boolean
        get() = collectionTitles.any { it != ReadList.DEFAULT_TITLE }

    /** Removing this article drops more than the default membership, so it needs confirmation. */
    val requiresUnsaveConfirmation: Boolean get() = isInUserCollection

    val hasActiveDownload: Boolean get() = offlineStatus == ArticleOfflineStatus.DOWNLOADING

    fun toJson(): JSONObject = jsonOf(
        "id" to id,
        "article" to title.logicalKey,
        "displayTitle" to title.displayTitle,
        "collections" to jsonArrayOf(collectionTitles),
        "isInDefaultCollection" to isInDefaultCollection,
        "requiresUnsaveConfirmation" to requiresUnsaveConfirmation,
        "offlineStatus" to offlineStatus.name,
        "downloadProgress" to downloadProgress
    )
}

/** One row of the Collections tab. The default collection is never a row here. */
data class SavedCollectionRow(
    val id: Long,
    val title: String,
    val description: String?,
    val articleCount: Int,
    val isDefault: Boolean
) {
    fun toJson(): JSONObject = jsonOf(
        "id" to id,
        "title" to title,
        "description" to description,
        "articleCount" to articleCount,
        "isDefault" to isDefault
    )
}

/**
 * Everything the Saved surface renders, for the tab that is currently selected.
 *
 * The state is reduced from the database projections plus the account and sync inputs; it is the
 * only thing the UI reads, and it always describes presentation rather than stored membership.
 */
data class SavedUiState(
    val selectedTab: SavedTab = SavedTab.ALL_ARTICLES,
    val searchQuery: String = "",
    val appliedSearchQuery: String = "",
    val articleFilter: ArticleFilter = ArticleFilter.ALL_ARTICLES,
    val articleSortMode: ReadingListSortMode = ReadingListSortMode.SORT_BY_NAME_ASC,
    val collectionSortMode: ReadingListSortMode = ReadingListSortMode.SORT_BY_NAME_ASC,
    val selectionEnabled: Boolean = false,
    val selectedPageIds: List<Long> = emptyList(),
    val isRefreshing: Boolean = false,
    val isLoading: Boolean = true,
    val onboarding: SavedOnboardingState = SavedOnboardingState.NONE,
    val feedback: SavedFeedback = SavedFeedback.NONE,
    val feedbackMessage: String? = null,
    val menuActions: List<SavedMenuAction> = emptyList(),
    val emptyState: SavedEmptyState = SavedEmptyState.LOADING,
    val recoveryAction: SavedRecoveryAction = SavedRecoveryAction.NONE,
    val articleRows: List<SavedArticleRow> = emptyList(),
    val collectionRows: List<SavedCollectionRow> = emptyList(),
    val undoDescription: String? = null
) {
    val undoAvailable: Boolean get() = undoDescription != null

    val totalSavedArticleCount: Int get() = articleRows.size

    fun toJson(): JSONObject = jsonOf(
        "selectedTab" to selectedTab.name,
        "searchQuery" to searchQuery,
        "appliedSearchQuery" to appliedSearchQuery,
        "articleFilter" to articleFilter.name,
        "articleSortMode" to articleSortMode.name,
        "collectionSortMode" to collectionSortMode.name,
        "selectionEnabled" to selectionEnabled,
        "selectedPageIds" to jsonArrayOf(selectedPageIds),
        "isRefreshing" to isRefreshing,
        "isLoading" to isLoading,
        "onboarding" to onboarding.name,
        "feedback" to feedback.name,
        "feedbackMessage" to feedbackMessage,
        "menuActions" to jsonArrayOf(menuActions.map { it.name }),
        "emptyState" to emptyStateJson(),
        "recoveryAction" to recoveryAction.name,
        "articleRows" to jsonArrayOf(articleRows.map { it.toJson() }),
        "collectionRows" to jsonArrayOf(collectionRows.map { it.toJson() }),
        "undoAvailable" to undoAvailable,
        "undoDescription" to undoDescription
    )

    private fun emptyStateJson(): JSONObject = when (val state = emptyState) {
        is SavedEmptyState.SEARCH_NO_RESULTS -> jsonOf("state" to "SEARCH_NO_RESULTS", "query" to state.query)
        else -> jsonOf("state" to state::class.simpleName)
    }
}

/** Sort helpers shared by both views. */
internal object SavedSorting {

    fun <T> byName(mode: ReadingListSortMode, key: (T) -> String): Comparator<T> =
        Comparator { left, right ->
            val comparison = key(left).lowercase().compareTo(key(right).lowercase())
            if (mode == ReadingListSortMode.SORT_BY_NAME_DESC) comparison.reversed() else comparison
        }

    fun <T> byRecency(
        mode: ReadingListSortMode,
        key: (T) -> String,
        recency: (T) -> Long
    ): Comparator<T> = when (mode) {
        ReadingListSortMode.SORT_BY_NEWEST_FIRST -> Comparator { left, right ->
            recency(right).compareTo(recency(left)).takeIf { it != 0 } ?: key(left).compareTo(key(right))
        }
        ReadingListSortMode.SORT_BY_OLDEST_FIRST -> Comparator { left, right ->
            recency(left).compareTo(recency(right)).takeIf { it != 0 } ?: key(left).compareTo(key(right))
        }
        else -> byName(mode, key)
    }
}

/** Availability projection helper shared by the article rows. */
internal fun ArticleAvailability.displayProgress(): Int = downloadProgress

