package org.wikipedia.readinglist

import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog

/** Why a requested change to saved content was refused. */
enum class LimitReason {
    DEFAULT_COLLECTION_PROTECTED,
    COLLECTION_LIMIT_REACHED,
    ARTICLE_LIMIT_REACHED,
    COLLECTION_UNAVAILABLE,
    ARTICLE_NOT_SAVED
}

/**
 * Result of a write against saved content.
 *
 * A [Rejected] write never touches stored membership: the requested addition is blocked, the
 * reason is reported, and every existing membership is left exactly as it was.
 */
sealed class MembershipChange {
    abstract val title: PageTitle

    data class Applied(
        override val title: PageTitle,
        val collectionTitles: List<String>,
        val addedCollection: String? = null,
        val removedCollection: String? = null,
        val wasAlreadySaved: Boolean = false
    ) : MembershipChange()

    data class Rejected(
        override val title: PageTitle,
        val reason: LimitReason,
        val message: String
    ) : MembershipChange()

    val isApplied: Boolean get() = this is Applied
}

/** Result of a collection-scoped action such as deletion. */
sealed class CollectionChange {
    data class Applied(val list: ReadList) : CollectionChange()
    data class Rejected(val list: ReadList, val reason: LimitReason, val message: String) : CollectionChange()

    val isApplied: Boolean get() = this is Applied
}

/** Result of an unsave request; the sheet asks for confirmation only when it is required. */
sealed class UnsaveOutcome {
    object Removed : UnsaveOutcome()
    data class NeedsConfirmation(val collectionTitles: List<String>) : UnsaveOutcome()
}

/**
 * Hard caps enforced by the Saved experience.
 *
 * A request that would cross a cap is refused up front with a reason the surface can show; no
 * partial write happens.
 */
object ReadingListLimits {
    /** Maximum number of user-created collections. */
    const val MAX_COLLECTIONS = 300

    /** Maximum number of articles a single collection may hold. */
    const val MAX_ARTICLES_PER_COLLECTION = 1000

    fun canCreateCollection(existingCollectionCount: Int): Boolean =
        existingCollectionCount < MAX_COLLECTIONS

    fun canAddArticle(currentArticleCount: Int): Boolean =
        currentArticleCount < MAX_ARTICLES_PER_COLLECTION

    fun describeCollectionLimit(): String =
        "You can keep up to $MAX_COLLECTIONS collections."

    fun describeArticleLimit(): String =
        "A collection can hold up to $MAX_ARTICLES_PER_COLLECTION articles."
}

/**
 * The only writer of saved content.
 *
 * Everything that changes membership - saving from an article, creating a collection, toggling a
 * membership, deleting rows - goes through this class, so limits, default-collection protection
 * and undo bookkeeping are applied consistently. Reads for the surfaces come from
 * [org.wikipedia.database.AppDatabase] projections instead.
 */
class ReadingListManager(
    private val database: org.wikipedia.database.AppDatabase,
    private val log: ProductionLog? = null
) {

    // ---------------------------------------------------------------- collections

    /** Returns the default collection, creating it on first use. */
    fun ensureDefaultCollection(): ReadList {
        database.getLists().firstOrNull { it.isDefault }?.let {
            log?.record("ReadingListManager.ensureDefaultCollection:hit")
            return it
        }
        val created = createCollection(ReadList.DEFAULT_TITLE, isDefault = true)
        log?.record("ReadingListManager.ensureDefaultCollection:created")
        return created
    }

    fun findListById(id: Long): ReadList? = database.getList(id)?.takeIf { !it.isDeleted }

    fun findListByTitle(title: String): ReadList? = database.getListByTitle(title)

    fun collections(): List<ReadList> = database.getLists()

    /** Collections a reader created themselves; the default collection is not one of them. */
    fun userCollections(): List<ReadList> = database.getLists().filter { !it.isDefault }

    fun createCollection(title: String, description: String? = null, isDefault: Boolean = false): ReadList {
        val existing = database.getListByTitle(title)
        if (existing != null) {
            log?.record("ReadingListManager.createCollection:existing:$title")
            return existing
        }
        val id = database.insertList(ReadList(id = 0, title = title, description = description, isDefault = isDefault))
        log?.record("ReadingListManager.createCollection:$title")
        return database.getList(id)!!
    }

    fun deleteCollection(list: ReadList): CollectionChange {
        if (list.isProtected) {
            log?.record("ReadingListManager.deleteCollection:refused_default")
            return CollectionChange.Rejected(
                list,
                LimitReason.DEFAULT_COLLECTION_PROTECTED,
                "${ReadList.DEFAULT_TITLE} cannot be deleted."
            )
        }
        log?.record("ReadingListManager.deleteCollection:${list.title}")
        database.deleteList(list)
        return CollectionChange.Applied(list)
    }

    /** Creation with the collection cap applied. */
    fun createUserCollection(title: String, description: String? = null): CollectionChange {
        val existing = database.getListByTitle(title)
        if (existing != null) {
            return CollectionChange.Applied(existing)
        }
        if (!ReadingListLimits.canCreateCollection(userCollections().size)) {
            log?.record("ReadingListManager.createUserCollection:limit_reached:$title")
            return CollectionChange.Rejected(
                ReadList(id = -1, title = title),
                LimitReason.COLLECTION_LIMIT_REACHED,
                ReadingListLimits.describeCollectionLimit()
            )
        }
        return CollectionChange.Applied(createCollection(title, description))
    }

    // ---------------------------------------------------------------- memberships

    /** Collections that currently contain [title], default collection first. */
    fun memberships(title: PageTitle): List<ReadList> {
        val containing = database.getAllPages()
            .filter { !it.isQueuedForDeletion && it.title.logicalKey == title.logicalKey }
            .mapNotNull { database.getList(it.listId)?.takeIf { list -> !list.isDeleted } }
        return containing.sortedByDescending { it.isDefault }
    }

    fun collectionTitles(title: PageTitle): List<String> = memberships(title).map { it.title }

    fun isSaved(title: PageTitle): Boolean = memberships(title).isNotEmpty()

    /**
     * Adds [title] to [list].
     *
     * Rejects - leaving all membership untouched - when the collection is gone or the
     * per-collection article cap would be crossed.
     */
    fun addPageToReadingList(list: ReadList, title: PageTitle, explicitId: Long? = null): MembershipChange {
        val target = database.getList(list.id)?.takeIf { !it.isDeleted }
        if (target == null) {
            log?.record("ReadingListManager.addPageToReadingList:missing_collection:${list.title}")
            return MembershipChange.Rejected(
                title,
                LimitReason.COLLECTION_UNAVAILABLE,
                "That collection is no longer available."
            )
        }
        val existing = database.getPage(target.id, title.logicalKey)
        if (existing != null && !existing.isQueuedForDeletion) {
            return MembershipChange.Applied(
                title = title,
                collectionTitles = collectionTitles(title),
                addedCollection = target.title,
                wasAlreadySaved = true
            )
        }
        val currentCount = database.getPages(target.id).count { !it.isQueuedForDeletion }
        if (!ReadingListLimits.canAddArticle(currentCount)) {
            log?.record("ReadingListManager.addPageToReadingList:limit_reached:${target.title}")
            return MembershipChange.Rejected(
                title,
                LimitReason.ARTICLE_LIMIT_REACHED,
                ReadingListLimits.describeArticleLimit()
            )
        }
        if (existing != null) {
            database.deletePage(existing)
        }
        val page = ReadingListPage(
            id = explicitId ?: 0L,
            listId = target.id,
            title = title,
            status = ReadingListPage.STATUS_NORMAL
        )
        database.insertPage(page)
        log?.record("ReadingListManager.addPageToReadingList:${target.title}:${title.logicalKey}")
        return MembershipChange.Applied(
            title = title,
            collectionTitles = collectionTitles(title),
            addedCollection = target.title
        )
    }

    fun removePageFromReadingList(listId: Long, title: PageTitle): Boolean {
        val page = database.getPage(listId, title.logicalKey) ?: return false
        database.deletePage(page)
        log?.record("ReadingListManager.removePageFromReadingList:$listId:${title.logicalKey}")
        return true
    }

    /** Removes every membership of [title] and returns the memberships that were removed. */
    fun removePageFromAllReadingLists(title: PageTitle): List<ReadList> {
        val removed = memberships(title)
        removed.forEach { removePageFromReadingList(it.id, title) }
        log?.record("ReadingListManager.removePageFromAllReadingLists:${title.logicalKey}:${removed.size}")
        return removed
    }

    /** Toggles membership of [title] in the collection identified by [collectionId]. */
    fun toggleCollection(title: PageTitle, collectionId: Long): MembershipChange {
        val list = findListById(collectionId)
        if (list == null) {
            // The collection was removed while the sheet was on screen. The row callback that is
            // still bound to it must not fall back to any other collection.
            log?.record("ReadingListManager.toggleCollection:collection_unavailable:$collectionId")
            return MembershipChange.Rejected(
                title,
                LimitReason.COLLECTION_UNAVAILABLE,
                "That collection is no longer available."
            )
        }
        val page = database.getPage(list.id, title.logicalKey)
        return if (page != null && !page.isQueuedForDeletion) {
            removePageFromReadingList(list.id, title)
            MembershipChange.Applied(
                title = title,
                collectionTitles = collectionTitles(title),
                removedCollection = list.title
            )
        } else {
            addPageToReadingList(list, title)
        }
    }

    /**
     * Stages every membership of [title] for removal. Staged rows stop being rendered as active
     * memberships immediately; they are still recoverable through undo.
     */
    fun queueArticleForDeletion(title: PageTitle): List<ReadingListPage> {
        val active = database.getAllPages()
            .filter { it.title.logicalKey == title.logicalKey && !it.isQueuedForDeletion }
        active.forEach { database.updatePage(it.copy(status = ReadingListPage.STATUS_QUEUE_FOR_DELETE)) }
        if (active.isNotEmpty()) {
            log?.record("ReadingListManager.queueArticleForDeletion:${title.logicalKey}:${active.size}")
        }
        return active
    }

    /** Physically drops [title] from every collection, used after the undo window closes. */
    fun purgeArticle(title: PageTitle) {
        database.deletePages { it.title.logicalKey == title.logicalKey }
        log?.record("ReadingListManager.purgeArticle:${title.logicalKey}")
    }
}

package org.wikipedia.readinglist

import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog

/** What an article looked like before a destructive action. */
data class ArticleMembershipSnapshot(
    val listId: Long,
    val listTitle: String,
    val title: PageTitle
)

/** What a collection looked like before a destructive action. */
data class CollectionSnapshot(
    val id: Long,
    val title: String,
    val description: String?,
    val isRemote: Boolean
)

/** A pending, reversible destructive action. */
sealed class UndoAction {
    abstract val description: String

    data class RemoveArticles(
        val articles: List<PageTitle>,
        val memberships: List<ArticleMembershipSnapshot>
    ) : UndoAction() {
        override val description: String get() = "Removed ${articles.size} article(s)"
    }

    data class RemoveCollections(
        val collections: List<CollectionSnapshot>
    ) : UndoAction() {
        override val description: String get() = "Removed ${collections.size} collection(s)"
    }
}

/**
 * Single-slot undo for destructive actions on the Saved surfaces.
 *
 * Deleting rows stages them so they vanish from the projection immediately while the action is
 * still reversible. Undo drops the staged rows and re-creates exactly the memberships - or the
 * collections - that existed before, by logical identity; database row ids may differ afterwards.
 * Rows that were not part of the action are never touched.
 */
class ReadingListUndo(
    private val manager: ReadingListManager,
    private val log: ProductionLog? = null
) {
    var pending: UndoAction? = null
        private set

    val isAvailable: Boolean get() = pending != null

    val description: String? get() = pending?.description

    fun trackArticles(articles: List<PageTitle>, memberships: List<ArticleMembershipSnapshot>) {
        if (articles.isEmpty()) {
            return
        }
        pending = UndoAction.RemoveArticles(articles, memberships)
        log?.record("ReadingListUndo.trackArticles:${articles.size}")
    }

    fun trackCollections(collections: List<CollectionSnapshot>) {
        if (collections.isEmpty()) {
            return
        }
        pending = UndoAction.RemoveCollections(collections)
        log?.record("ReadingListUndo.trackCollections:${collections.size}")
    }

    /** Restores the pending action. Returns false when there is nothing to restore. */
    fun undo(): Boolean {
        val action = pending ?: return false
        when (action) {
            is UndoAction.RemoveArticles -> {
                action.articles.forEach { manager.purgeArticle(it) }
                action.memberships.forEach { membership ->
                    val list = manager.findListById(membership.listId)
                        ?: manager.findListByTitle(membership.listTitle)
                    if (list != null) {
                        manager.addPageToReadingList(list, membership.title)
                    }
                }
            }
            is UndoAction.RemoveCollections -> {
                action.collections.forEach { snapshot ->
                    manager.createCollection(
                        title = snapshot.title,
                        description = snapshot.description,
                        isRemote = snapshot.isRemote
                    )
                }
            }
        }
        pending = null
        log?.record("ReadingListUndo.undo")
        return true
    }

    fun clear() {
        pending = null
    }
}

package org.wikipedia.readinglist

import org.wikipedia.database.KeyValueStore
import org.wikipedia.page.PageTitle

/**
 * Outcome of a reading list synchronization pass.
 *
 * The refresh spinner on the Saved surface stays up from [isRunning] until a terminal event
 * arrives; only the transport reports those events, and it is a leaf boundary.
 */
class ReadingListSyncEvent private constructor(
    val status: Status,
    val cause: Throwable? = null
) {
    val isRunning: Boolean get() = status == Status.RUNNING
    val isError: Boolean get() = status == Status.ERROR

    val isTerminal: Boolean get() = status == Status.COMPLETED || status == Status.ERROR

    enum class Status { RUNNING, COMPLETED, ERROR }

    companion object {
        fun started() = ReadingListSyncEvent(Status.RUNNING)

        fun finished() = ReadingListSyncEvent(Status.COMPLETED)

        fun error(cause: Throwable? = null) = ReadingListSyncEvent(Status.ERROR, cause)
    }
}

/**
 * Reading list synchronization.
 *
 * The Saved surface owns two things here: whether sync is enabled for the account, and the
 * lifecycle of a refresh. Dispatching a sync is an external effect - the transport is a leaf -
 * but deciding *whether* to dispatch, keeping the refresh state alive until an event arrives,
 * and applying the resulting memberships are all application-owned.
 */
class ReadingListSync(
    private val manager: ReadingListManager,
    private val store: KeyValueStore,
    private val log: org.wikipedia.util.ProductionLog? = null
) {
    private val listeners = mutableListOf<(ReadingListSyncEvent) -> Unit>()

    /** One remote collection as reported by the sync transport. */
    data class RemoteList(val title: String, val articles: List<PageTitle>)

    /** Transport that performs the actual network work; a leaf boundary. */
    fun interface Transport {
        fun start(account: org.wikipedia.auth.AccountInfo, remote: List<RemoteList>)
    }

    var transport: Transport? = null

    fun addListener(listener: (ReadingListSyncEvent) -> Unit) {
        listeners.add(listener)
    }

    fun removeListener(listener: (ReadingListSyncEvent) -> Unit) {
        listeners.remove(listener)
    }

    fun isSyncEnabled(): Boolean = store.getBoolean(KEY_SYNC_ENABLED, false)

    fun setSyncEnabled(enabled: Boolean) {
        store.putBoolean(KEY_SYNC_ENABLED, enabled)
        log?.record("ReadingListSync.setSyncEnabled:$enabled")
    }

    /**
     * Starts a sync pass and applies the resulting memberships locally so the database
     * projections update immediately, while the pass itself is still running.
     */
    fun start(account: org.wikipedia.auth.AccountInfo, remote: List<RemoteList>) {
        log?.record("ReadingListSync.start")
        emit(ReadingListSyncEvent.started())
        applyRemote(remote)
        transport?.start(account, remote)
    }

    /** Delivers a transport-reported event to every listener. */
    fun onEvent(event: ReadingListSyncEvent) {
        log?.record("ReadingListSync.onEvent:${event.status}")
        emit(event)
    }

    private fun applyRemote(remote: List<RemoteList>) {
        remote.forEach { list ->
            val target = manager.findListByTitle(list.title) ?: manager.createCollection(list.title, isRemote = true)
            list.articles.forEach { manager.addPageToReadingList(target, it) }
        }
    }

    private fun emit(event: ReadingListSyncEvent) {
        listeners.toList().forEach { it(event) }
    }

    companion object {
        private const val KEY_SYNC_ENABLED = "reading_list_sync_enabled"
    }
}

package org.wikipedia.readinglist

import org.wikipedia.database.KeyValueStore

/**
 * Durable Saved preferences.
 *
 * Sort mode is a per-view setting: what the reader last chose for All articles and what they last
 * chose for Collections are stored under separate keys, so changing one never disturbs the other
 * and both survive a restart.
 */
class SavedPreferences(private val store: KeyValueStore) {

    var articleSortMode: ReadingListSortMode
        get() = ReadingListSortMode.fromOrdinal(store.getString(KEY_ARTICLE_SORT)?.toIntOrNull() ?: 0)
        set(value) {
            store.putString(KEY_ARTICLE_SORT, value.ordinal.toString())
        }

    var collectionSortMode: ReadingListSortMode
        get() = ReadingListSortMode.fromOrdinal(store.getString(KEY_COLLECTION_SORT)?.toIntOrNull() ?: 0)
        set(value) {
            store.putString(KEY_COLLECTION_SORT, value.ordinal.toString())
        }

    var syncReminderSeen: Boolean
        get() = store.getBoolean(KEY_SYNC_REMINDER_SEEN, false)
        set(value) {
            store.putBoolean(KEY_SYNC_REMINDER_SEEN, value)
        }

    companion object {
        const val KEY_ARTICLE_SORT = "saved_sort_mode_articles"
        const val KEY_COLLECTION_SORT = "saved_sort_mode_collections"
        private const val KEY_SYNC_REMINDER_SEEN = "saved_sync_reminder_seen"
    }
}

package org.wikipedia.readinglist

import org.wikipedia.auth.AccountInfo
import org.wikipedia.auth.AccountStateHolder
import org.wikipedia.database.ChangeListener
import org.wikipedia.database.QueryFlow
import org.wikipedia.database.Subscription
import org.wikipedia.offline.ArticleOfflineStore
import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog

/**
 * Owns the state of the Saved experience.
 *
 * The database projections are the source of truth for membership; everything else - the
 * selected tab, the search scope, the All articles filter, the two independent sort modes,
 * selection, the refresh spinner, onboarding and feedback - is presentation that is reduced on
 * top of those projections. Because the ViewModel subscribes to the projections, any write -
 * from the Save sheet, from a destructive action, or from sync - re-reduces the rows without
 * anyone rebuilding a page by hand.
 */
class SavedViewModel(
    private val manager: ReadingListManager,
    private val undo: ReadingListUndo,
    private val sync: ReadingListSync,
    private val account: AccountStateHolder,
    private val offlineStore: ArticleOfflineStore,
    private val preferences: SavedPreferences,
    private val scheduler: SavedScheduler,
    private val readingListsWithPages: QueryFlow<List<ReadingListWithPages>>,
    private val log: ProductionLog
) {
    private val listeners = mutableListOf<(SavedUiState) -> Unit>()

    private var selectedTab = SavedTab.ALL_ARTICLES
    private var searchQuery = ""
    private var appliedSearchQuery = ""
    private var articleFilter = ArticleFilter.ALL_ARTICLES
    private var selectionEnabled = false
    private val selectedIds = LinkedHashSet<Long>()
    private var isRefreshing = false
    private var isLoading = true
    private var sharedCollectionPending = false
    private var feedback = SavedFeedback.NONE
    private var feedbackMessage: String? = null
    private var articleRows: List<SavedArticleRow> = emptyList()
    private var collectionRows: List<SavedCollectionRow> = emptyList()
    private var pendingBulkDeleteConfirmation: List<SavedArticleRow> = emptyList()
    private var pendingSearch: ScheduledTask? = null
    private var projections: List<ReadingListWithPages> = emptyList()

    /** Remote state the next sync pass should apply; supplied by the sync transport owner. */
    var pendingRemoteSync: List<ReadingListSync.RemoteList> = emptyList()

    val uiState: SavedUiState
        get() = SavedUiState(
            selectedTab = selectedTab,
            searchQuery = searchQuery,
            appliedSearchQuery = appliedSearchQuery,
            articleFilter = articleFilter,
            articleSortMode = preferences.articleSortMode,
            collectionSortMode = preferences.collectionSortMode,
            selectionEnabled = selectionEnabled,
            selectedPageIds = selectedIds.toList(),
            isRefreshing = isRefreshing,
            isLoading = isLoading,
            onboarding = resolveOnboarding(),
            feedback = feedback,
            feedbackMessage = feedbackMessage,
            menuActions = resolveMenuActions(),
            emptyState = resolveEmptyState(),
            recoveryAction = resolveRecoveryAction(),
            articleRows = articleRows,
            collectionRows = collectionRows,
            undoDescription = undo.description
        )

    val requiresBulkDeleteConfirmation: Boolean get() = pendingBulkDeleteConfirmation.isNotEmpty()

    fun observe(listener: (SavedUiState) -> Unit): Subscription {
        listeners.add(listener)
        listener(uiState)
        return Subscription { listeners.remove(listener) }
    }

    // ------------------------------------------------------------------ lifecycle

    private fun emit() {
        val state = uiState
        listeners.toList().forEach { it(state) }
    }

    private fun recompute() {
        val availability = offlineStore.observe().value
        articleRows = buildArticleRows(availability)
        collectionRows = buildCollectionRows()
        isLoading = false
        emit()
    }

    private fun buildArticleRows(availability: Map<String, org.wikipedia.offline.ArticleAvailability>): List<SavedArticleRow> {
        val accumulator = LinkedHashMap<String, ArticleAccumulator>()
        projections.forEach { projection ->
            val list = projection.list
            projection.pages.forEach { page ->
                val entry = accumulator.getOrPut(page.title.logicalKey) { ArticleAccumulator(page.title) }
                entry.collectionTitles.add(list.title to list.isDefault)
                if (list.isDefault || entry.canonicalId == null) {
                    entry.canonicalId = page.id
                }
                entry.inDefaultCollection = entry.inDefaultCollection || list.isDefault
                entry.recency = maxOf(entry.recency, page.mtime)
            }
        }
        val rows = accumulator.values.map { entry ->
            val offline = availability[entry.title.logicalKey]
            SavedArticleRow(
                id = entry.canonicalId ?: 0L,
                title = entry.title,
                collectionTitles = entry.collectionTitles.sortedByDescending { it.second }.map { it.first },
                isInDefaultCollection = entry.inDefaultCollection,
                offlineStatus = offline?.status ?: org.wikipedia.offline.ArticleOfflineStatus.NOT_DOWNLOADED,
                downloadProgress = offline?.downloadProgress
                    ?: org.wikipedia.offline.ArticleAvailability.NO_ACTIVE_DOWNLOAD
            )
        }
        return rows
            .filter { matchesSearch(it.title, appliedSearchQuery) }
            .filter { row ->
                articleFilter == ArticleFilter.ALL_ARTICLES || !row.isInUserCollection
            }
            .sortedWith(
                SavedSorting.byRecency(
                    mode = preferences.articleSortMode,
                    key = { it.title.displayTitle },
                    recency = { accRecency(accumulator, it.title.logicalKey) }
                )
            )
    }

    private fun buildCollectionRows(): List<SavedCollectionRow> {
        val query = appliedSearchQuery
        return projections
            .filter { !it.list.isDefault }
            .filter { query.isBlank() || it.list.title.contains(query, ignoreCase = true) }
            .map { projection ->
                SavedCollectionRow(
                    id = projection.list.id,
                    title = projection.list.title,
                    description = projection.list.description,
                    articleCount = projection.pages.size,
                    isDefault = projection.list.isDefault
                )
            }
            .sortedWith(
                SavedSorting.byRecency(
                    mode = preferences.collectionSortMode,
                    key = { it.title },
                    recency = { projectionRecency(it.id) }
                )
            )
    }

    private fun accRecency(accumulator: Map<String, ArticleAccumulator>, key: String): Long =
        accumulator[key]?.recency ?: 0L

    private fun projectionRecency(listId: Long): Long =
        projections.firstOrNull { it.list.id == listId }?.pages?.maxOfOrNull { it.mtime } ?: 0L

    private fun matchesSearch(title: PageTitle, query: String): Boolean {
        if (query.isBlank()) {
            return true
        }
        return title.displayTitle.contains(query, ignoreCase = true) ||
            title.apiTitle.contains(query, ignoreCase = true)
    }

    private fun visibleRows(): List<Long> = when (selectedTab) {
        SavedTab.ALL_ARTICLES -> articleRows.map { it.id }
        SavedTab.COLLECTIONS -> collectionRows.map { it.id }
    }

    private fun resolveMenuActions(): List<SavedMenuAction> {
        val base = when (selectedTab) {
            SavedTab.ALL_ARTICLES -> listOf(SavedMenuAction.SORT, SavedMenuAction.FILTER)
            SavedTab.COLLECTIONS -> listOf(SavedMenuAction.SORT, SavedMenuAction.NEW_COLLECTION)
        }
        if (visibleRows().isEmpty()) {
            return base
        }
        return base + listOf(SavedMenuAction.SELECT_ALL, SavedMenuAction.DELETE)
    }

    private fun resolveSortChoices(): List<ReadingListSortMode> = when (selectedTab) {
        SavedTab.ALL_ARTICLES -> ReadingListSortMode.entries.toList()
        SavedTab.COLLECTIONS -> listOf(
            ReadingListSortMode.SORT_BY_NAME_ASC,
            ReadingListSortMode.SORT_BY_NAME_DESC,
            ReadingListSortMode.SORT_BY_NEWEST_FIRST
        )
    }

    /** Sort choices offered for the active view. */
    fun sortChoices(): List<ReadingListSortMode> = resolveSortChoices()

    private fun resolveEmptyState(): SavedEmptyState {
        if (isLoading) {
            return SavedEmptyState.LOADING
        }
        val rowsAreEmpty = visibleRows().isEmpty()
        if (!rowsAreEmpty) {
            return SavedEmptyState.NONE
        }
        if (appliedSearchQuery.isNotBlank()) {
            return SavedEmptyState.SEARCH_NO_RESULTS(appliedSearchQuery)
        }
        return when (selectedTab) {
            SavedTab.ALL_ARTICLES -> SavedEmptyState.NO_SAVED_ARTICLES
            SavedTab.COLLECTIONS -> SavedEmptyState.NO_COLLECTIONS
        }
    }

    private fun resolveRecoveryAction(): SavedRecoveryAction {
        return when (resolveEmptyState()) {
            is SavedEmptyState.SEARCH_NO_RESULTS -> SavedRecoveryAction.CLEAR_SEARCH
            SavedEmptyState.NO_COLLECTIONS -> SavedRecoveryAction.CREATE_COLLECTION
            SavedEmptyState.NO_SAVED_ARTICLES ->
                if (account.account.isLoggedIn) SavedRecoveryAction.START_SYNC else SavedRecoveryAction.LOG_IN
            else -> SavedRecoveryAction.NONE
        }
    }

    private fun resolveOnboarding(): SavedOnboardingState = when {
        sharedCollectionPending -> SavedOnboardingState.SHARED_COLLECTION_RECEIVED
        feedback == SavedFeedback.LOGIN_REQUIRED -> SavedOnboardingState.LOGIN_PROMPT
        account.account.isLoggedIn && !sync.isSyncEnabled() -> SavedOnboardingState.SYNC_REMINDER
        else -> SavedOnboardingState.NONE
    }

    // ------------------------------------------------------------------ tab and search

    fun onScreenOpened() {
        log.record("SavedViewModel.onScreenOpened")
        recompute()
    }

    /**
     * Switches the visible view. Rows, search scope, sort, menu actions, empty state and
     * onboarding are re-derived for the new view; nothing about stored membership changes and the
     * default collection stays in storage either way.
     */
    fun onSelectTab(tab: SavedTab) {
        if (tab == selectedTab) {
            return
        }
        log.record("SavedViewModel.onSelectTab:${tab.name}")
        selectedTab = tab
        if (tab == SavedTab.COLLECTIONS) {
            // The narrowing filter only exists on All articles.
            articleFilter = ArticleFilter.ALL_ARTICLES
        }
        selectionEnabled = false
        selectedIds.clear()
        pendingBulkDeleteConfirmation = emptyList()
        recompute()
    }

    /**
     * Records what the reader typed. A non-empty query is only applied once typing pauses for
     * [SavedScheduler.SEARCH_DEBOUNCE_DELAY_MS]; clearing the field applies at once.
     */
    fun onSearchQueryChanged(query: String) {
        log.record("SavedViewModel.onSearchQueryChanged:$query")
        searchQuery = query
        pendingSearch?.cancel()
        if (query.isBlank()) {
            appliedSearchQuery = ""
            recompute()
            return
        }
        pendingSearch = scheduler.postDelayed(SavedScheduler.SEARCH_DEBOUNCE_DELAY_MS) {
            applySearchQuery(query)
        }
        emit()
    }

    /** Applies the debounced query to the rows of the active tab only. */
    fun applySearchQuery(query: String) {
        log.record("SavedViewModel.applySearchQuery:$query")
        searchQuery = query
        appliedSearchQuery = query
        recompute()
    }

    fun onClearSearch() {
        pendingSearch?.cancel()
        pendingSearch = null
        searchQuery = ""
        appliedSearchQuery = ""
        feedback = SavedFeedback.NONE
        feedbackMessage = null
        recompute()
    }

    fun onFilterSelected(filter: ArticleFilter) {
        log.record("SavedViewModel.onFilterSelected:${filter.name}")
        articleFilter = filter
        recompute()
    }

    /** Applies a sort choice to the active view and persists it under that view's own key. */
    fun onSortSelected(mode: ReadingListSortMode) {
        if (selectedTab == SavedTab.ALL_ARTICLES) {
            log.record("SavedViewModel.onSortSelected:articles:${mode.name}")
            preferences.articleSortMode = mode
        } else {
            log.record("SavedViewModel.onSortSelected:collections:${mode.name}")
            preferences.collectionSortMode = mode
        }
        recompute()
    }

    // ------------------------------------------------------------------ selection

    fun onStartSelectionMode() {
        log.record("SavedViewModel.onStartSelectionMode")
        selectionEnabled = true
        emit()
    }

    fun onToggleSelection(rowId: Long) {
        log.record("SavedViewModel.onToggleSelection:$rowId")
        selectionEnabled = true
        if (rowId in visibleRows()) {
            if (!selectedIds.add(rowId)) {
                selectedIds.remove(rowId)
            }
        }
        emit()
    }

    /**
     * Selects every row currently visible. Because All articles is de-duplicated, one logical
     * article contributes exactly one id, and rows hidden by the active filter are not selected.
     */
    fun onSelectAllVisible() {
        log.record("SavedViewModel.onSelectAllVisible")
        selectionEnabled = true
        val visible = visibleRows()
        selectedIds.clear()
        selectedIds.addAll(visible)
        emit()
    }

    fun onClearSelection() {
        log.record("SavedViewModel.onClearSelection")
        selectionEnabled = false
        selectedIds.clear()
        pendingBulkDeleteConfirmation = emptyList()
        emit()
    }

    // ------------------------------------------------------------------ destructive actions

    /**
     * Runs the destructive action valid for the active row type.
     *
     * On All articles an article held by a user-created collection is only staged for removal
     * after the reader confirms; on Collections the default collection is never a row and can
     * never be deleted. Both paths are reversible through undo.
     */
    fun onDeleteSelected() {
        log.record("SavedViewModel.onDeleteSelected:${selectedTab.name}")
        if (selectedIds.isEmpty()) {
            feedback = SavedFeedback.NOTHING_SELECTED
            feedbackMessage = null
            emit()
            return
        }
        when (selectedTab) {
            SavedTab.ALL_ARTICLES -> {
                val rows = articleRows.filter { it.id in selectedIds }
                if (rows.isEmpty()) {
                    feedback = SavedFeedback.NOTHING_SELECTED
                    emit()
                    return
                }
                if (rows.any { it.requiresUnsaveConfirmation }) {
                    pendingBulkDeleteConfirmation = rows
                    feedback = SavedFeedback.NONE
                    feedbackMessage = null
                    emit()
                    return
                }
                stageArticleRemoval(rows)
            }
            SavedTab.COLLECTIONS -> stageCollectionRemoval()
        }
    }

    /** Confirms a bulk removal that touches at least one user-created collection. */
    fun onConfirmDeleteSelected() {
        val rows = pendingBulkDeleteConfirmation
        log.record("SavedViewModel.onConfirmDeleteSelected:${rows.size}")
        pendingBulkDeleteConfirmation = emptyList()
        if (rows.isNotEmpty()) {
            stageArticleRemoval(rows)
        } else {
            emit()
        }
    }

    fun onCancelDeleteSelected() {
        log.record("SavedViewModel.onCancelDeleteSelected")
        pendingBulkDeleteConfirmation = emptyList()
        emit()
    }

    private fun stageArticleRemoval(rows: List<SavedArticleRow>) {
        val snapshots = rows.flatMap { row ->
            manager.memberships(row.title).map { membership ->
                ArticleMembershipSnapshot(membership.id, membership.title, row.title)
            }
        }
        rows.forEach { manager.queueArticleForDeletion(it.title) }
        undo.trackArticles(rows.map { it.title }, snapshots)
        selectedIds.clear()
        selectionEnabled = false
        feedback = SavedFeedback.ARTICLES_DELETED
        feedbackMessage = rows.joinToString { it.title.displayTitle }
        recompute()
    }

    private fun stageCollectionRemoval() {
        val selected = collectionRows.filter { it.id in selectedIds && !it.isDefault }
        if (selected.isEmpty()) {
            feedback = SavedFeedback.NOTHING_SELECTED
            emit()
            return
        }
        val snapshots = selected.map { CollectionSnapshot(it.id, it.title, it.description, isRemote = false) }
        selected.forEach { row ->
            manager.findListById(row.id)?.let { manager.deleteCollection(it) }
        }
        undo.trackCollections(snapshots)
        selectedIds.clear()
        selectionEnabled = false
        feedback = SavedFeedback.COLLECTIONS_DELETED
        feedbackMessage = selected.joinToString { it.title }
        recompute()
    }

    /** Restores whatever the last destructive action removed, leaving unrelated rows alone. */
    fun onUndoDelete() {
        log.record("SavedViewModel.onUndoDelete")
        if (!undo.undo()) {
            feedback = SavedFeedback.NONE
            emit()
            return
        }
        feedback = SavedFeedback.RESTORED
        feedbackMessage = null
        recompute()
    }

    // ------------------------------------------------------------------ sync and account

    /**
     * Pull-to-refresh. Only an account that is signed in and not temporary may start a sync; for
     * anyone else the refresh ends immediately with a login prompt and nothing is dispatched.
     */
    fun onPullToRefresh() {
        log.record("SavedViewModel.onPullToRefresh")
        val info = account.account
        if (!info.isEligibleForSync) {
            isRefreshing = false
            feedback = SavedFeedback.LOGIN_REQUIRED
            feedbackMessage = "Log in to sync your saved articles."
            log.record("SavedViewModel.onPullToRefresh:login_prompt")
            emit()
            return
        }
        feedback = SavedFeedback.NONE
        feedbackMessage = null
        isRefreshing = true
        sync.start(info, pendingRemoteSync)
        recompute()
    }

    fun onSyncEvent(event: ReadingListSyncEvent) {
        log.record("SavedViewModel.onSyncEvent:${event.status}")
        when {
            event.isRunning -> {
                isRefreshing = true
                recompute()
            }
            event.isError -> {
                isRefreshing = false
                feedback = SavedFeedback.SYNC_FAILED
                recompute()
            }
            else -> {
                isRefreshing = false
                feedback = SavedFeedback.SYNCED
                recompute()
            }
        }
    }

    fun onLoginCompleted(info: AccountInfo) {
        log.record("SavedViewModel.onLoginCompleted:${info.userName}")
        account.update(info)
        // Signing in turns reading list synchronization on for the account.
        sync.setSyncEnabled(info.isEligibleForSync)
        feedback = SavedFeedback.NONE
        feedbackMessage = null
        recompute()
    }

    fun onLogout() {
        log.record("SavedViewModel.onLogout")
        account.onLogout()
        sync.setSyncEnabled(false)
        feedback = SavedFeedback.NONE
        recompute()
    }

    fun onSyncPreferenceChanged(enabled: Boolean) {
        log.record("SavedViewModel.onSyncPreferenceChanged:$enabled")
        sync.setSyncEnabled(enabled)
        preferences.syncReminderSeen = !enabled
        recompute()
    }

    fun onSharedCollectionReceived(collectionTitle: String) {
        log.record("SavedViewModel.onSharedCollectionReceived:$collectionTitle")
        val existing = manager.findListByTitle(collectionTitle)
        if (existing == null) {
            manager.createCollection(collectionTitle, isRemote = true)
        }
        sharedCollectionPending = true
        feedback = SavedFeedback.NONE
        recompute()
    }

    fun onDismissOnboarding() {
        log.record("SavedViewModel.onDismissOnboarding")
        sharedCollectionPending = false
        preferences.syncReminderSeen = true
        recompute()
    }

    // ------------------------------------------------------------------ helpers used by the sheet

    fun createCollection(title: String, description: String? = null): CollectionChange {
        log.record("SavedViewModel.createCollection:$title")
        val result = manager.createUserCollection(title, description)
        feedback = when {
            result is CollectionChange.Applied -> SavedFeedback.COLLECTION_CREATED
            else -> SavedFeedback.LIMIT_REACHED
        }
        feedbackMessage = (result as? CollectionChange.Rejected)?.message
        recompute()
        return result
    }

    fun reportLimitRejection(rejection: MembershipChange.Rejected) {
        log.record("SavedViewModel.reportLimitRejection:${rejection.reason}")
        feedback = if (rejection.reason == LimitReason.COLLECTION_UNAVAILABLE) {
            SavedFeedback.COLLECTION_UNAVAILABLE
        } else {
            SavedFeedback.LIMIT_REACHED
        }
        feedbackMessage = rejection.message
        emit()
    }

    private class ArticleAccumulator(val title: PageTitle) {
        var canonicalId: Long? = null
        var inDefaultCollection = false
        var recency = 0L
        val collectionTitles = mutableListOf<Pair<String, Boolean>>()
    }

    init {
        log.record("SavedViewModel.init")
        readingListsWithPages.observe(ChangeListener { projection ->
            projections = projection
            recompute()
        })
        offlineStore.observe()
        account.observe()
    }
}

