package org.wikipedia.readinglist

import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog

/**
 * The sheet a reader opens from any article entry point.
 *
 * Opening it for a [PageTitle] saves the article if it is not saved yet and then lists the
 * collections it currently belongs to. From there the reader can create a collection, add or
 * remove the article from any collection, or unsave the article entirely. Unsaving an article
 * that belongs to a user-created collection asks for confirmation first; cancelling that
 * confirmation leaves every membership exactly as it was.
 */
class SaveArticleSheetDialog(
    val pageTitle: PageTitle,
    private val actions: ReadingListArticleActions,
    private val onFeedback: (SavedFeedback, String?) -> Unit,
    private val log: ProductionLog
) {
    /** Collections a reader may add the article to; the default collection is not offered. */
    val selectableCollections: List<ReadList>
        get() = state.collections.filter { !it.isDefault }

    private val state: ArticleSheetState = actions.sheetState(pageTitle)

    val isSaved: Boolean get() = state.isSaved
    val memberships: List<ReadList> get() = state.collections
    val pendingUnsaveConfirmation: Boolean get() = state.pendingUnsaveConfirmation

    init {
        log.record("SaveArticleSheetDialog.onCreate:${pageTitle.logicalKey}")
        // Opening the sheet for an article makes sure it is saved, then shows its memberships.
        when (val change = actions.ensureSaved(pageTitle)) {
            is MembershipChange.Applied -> {
                state.markResolved(change.title)
                state.refresh(actions)
                onFeedback(SavedFeedback.ARTICLE_SAVED, change.title.displayTitle)
            }
            is MembershipChange.Rejected -> onFeedback(SavedFeedback.LIMIT_REACHED, change.message)
        }
    }

    /** Applies a pending collection-row callback that was rendered before a recomposition. */
    fun onCollectionRowToggled(collectionId: Long): MembershipChange {
        log.record("SaveArticleSheetDialog.onCollectionRowToggled:$collectionId")
        val result = actions.toggleCollection(state.resolvedTitle, collectionId)
        state.refresh(actions)
        when (result) {
            is MembershipChange.Applied -> onFeedback(SavedFeedback.NONE, null)
            is MembershipChange.Rejected -> onFeedback(SavedFeedback.COLLECTION_UNAVAILABLE, result.message)
        }
        return result
    }

    fun onCreateCollectionClicked(collectionTitle: String): MembershipChange {
        log.record("SaveArticleSheetDialog.onCreateCollectionClicked:$collectionTitle")
        val result = actions.createCollectionAndAdd(state.resolvedTitle, collectionTitle)
        state.lastChange = result
        state.refresh(actions)
        when (result) {
            is MembershipChange.Applied -> onFeedback(SavedFeedback.COLLECTION_CREATED, collectionTitle)
            is MembershipChange.Rejected -> onFeedback(SavedFeedback.LIMIT_REACHED, result.message)
        }
        return result
    }

    /** Removes the article from every collection, after confirmation when one is required. */
    fun onUnsaveClicked(): UnsaveOutcome {
        log.record("SaveArticleSheetDialog.onUnsaveClicked")
        val outcome = actions.unsave(state.resolvedTitle)
        when (outcome) {
            is UnsaveOutcome.Removed -> {
                state.pendingUnsaveConfirmation = false
                state.refresh(actions)
                onFeedback(SavedFeedback.ARTICLE_UNSAVED, state.resolvedTitle.displayTitle)
            }
            is UnsaveOutcome.NeedsConfirmation -> {
                state.pendingUnsaveConfirmation = true
                state.confirmationCollections = outcome.collectionTitles
            }
        }
        return outcome
    }

    fun onConfirmUnsaveClicked(): UnsaveOutcome {
        log.record("SaveArticleSheetDialog.onConfirmUnsaveClicked")
        actions.confirmUnsave(state.resolvedTitle)
        state.pendingUnsaveConfirmation = false
        state.confirmationCollections = emptyList()
        state.refresh(actions)
        onFeedback(SavedFeedback.ARTICLE_UNSAVED, state.resolvedTitle.displayTitle)
        return UnsaveOutcome.Removed
    }

    /**
     * Dismisses the confirmation. Nothing is mutated here: the unsave only ever happens through
     * [onConfirmUnsaveClicked], so cancelling leaves every membership intact.
     */
    fun onUnsaveConfirmationCancelled() {
        log.record("SaveArticleSheetDialog.onUnsaveConfirmationCancelled")
        state.pendingUnsaveConfirmation = false
        state.confirmationCollections = emptyList()
        state.refresh(actions)
    }

    fun onDismiss() {
        log.record("SaveArticleSheetDialog.onDismiss")
        state.pendingUnsaveConfirmation = false
    }
}

package org.wikipedia.readinglist

import org.wikipedia.auth.AccountInfo
import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog

/**
 * The Saved page.
 *
 * It owns no state of its own: every callback forwards to [SavedViewModel] and re-renders from
 * the state it publishes. The class is the page's wiring - tabs, the search field, the filter, the
 * sort sheet, the selection bar, the refresh gesture, onboarding prompts and the Save sheet entry
 * point - which is what the rest of the app talks to.
 */
class ReadingListsFragment(
    private val viewModel: SavedViewModel,
    private val log: ProductionLog
) {
    /** Latest published state; the page renders exactly this. */
    val uiState: SavedUiState get() = viewModel.uiState

    fun onCreateView() {
        log.record("ReadingListsFragment.onCreateView")
        viewModel.onScreenOpened()
    }

    fun onSelectTab(tab: SavedTab) {
        log.record("ReadingListsFragment.onSelectTab:${tab.name}")
        viewModel.onSelectTab(tab)
    }

    /** Wired to the search field's text listener. */
    fun onSearchQueryChanged(query: String) {
        log.record("ReadingListsFragment.onSearchQueryChanged")
        viewModel.onSearchQueryChanged(query)
    }

    fun onClearSearch() {
        log.record("ReadingListsFragment.onClearSearch")
        viewModel.onClearSearch()
    }

    fun onFilterSelected(filter: ArticleFilter) {
        log.record("ReadingListsFragment.onFilterSelected:${filter.name}")
        viewModel.onFilterSelected(filter)
    }

    fun onSortSelected(mode: ReadingListSortMode) {
        log.record("ReadingListsFragment.onSortSelected:${mode.name}")
        viewModel.onSortSelected(mode)
    }

    fun onStartSelectionMode() {
        log.record("ReadingListsFragment.onStartSelectionMode")
        viewModel.onStartSelectionMode()
    }

    fun onToggleSelection(rowId: Long) {
        log.record("ReadingListsFragment.onToggleSelection:$rowId")
        viewModel.onToggleSelection(rowId)
    }

    fun onSelectAllVisible() {
        log.record("ReadingListsFragment.onSelectAllVisible")
        viewModel.onSelectAllVisible()
    }

    fun onClearSelection() {
        log.record("ReadingListsFragment.onClearSelection")
        viewModel.onClearSelection()
    }

    fun onDeleteSelected() {
        log.record("ReadingListsFragment.onDeleteSelected")
        viewModel.onDeleteSelected()
    }

    fun onConfirmDeleteSelected() {
        log.record("ReadingListsFragment.onConfirmDeleteSelected")
        viewModel.onConfirmDeleteSelected()
    }

    fun onCancelDeleteSelected() {
        log.record("ReadingListsFragment.onCancelDeleteSelected")
        viewModel.onCancelDeleteSelected()
    }

    /** Wired to the undo bar of a destructive action. */
    fun onUndo() {
        log.record("ReadingListsFragment.onUndo")
        viewModel.onUndoDelete()
    }

    /** Wired to the pull-to-refresh gesture. */
    fun onPullToRefresh() {
        log.record("ReadingListsFragment.onPullToRefresh")
        viewModel.onPullToRefresh()
    }

    fun onLoginStateChanged(account: AccountInfo) {
        log.record("ReadingListsFragment.onLoginStateChanged:${account.userName}")
        viewModel.onLoginCompleted(account)
    }

    fun onLogout() {
        log.record("ReadingListsFragment.onLogout")
        viewModel.onLogout()
    }

    fun onSyncPreferenceChanged(enabled: Boolean) {
        log.record("ReadingListsFragment.onSyncPreferenceChanged:$enabled")
        viewModel.onSyncPreferenceChanged(enabled)
    }

    fun onSharedCollectionReceived(collectionTitle: String) {
        log.record("ReadingListsFragment.onSharedCollectionReceived")
        viewModel.onSharedCollectionReceived(collectionTitle)
    }

    fun onDismissOnboarding() {
        log.record("ReadingListsFragment.onDismissOnboarding")
        viewModel.onDismissOnboarding()
    }

    fun onRecoveryAction() {
        log.record("ReadingListsFragment.onRecoveryAction:${uiState.recoveryAction}")
        when (uiState.recoveryAction) {
            SavedRecoveryAction.CLEAR_SEARCH -> viewModel.onClearSearch()
            SavedRecoveryAction.START_SYNC -> viewModel.onPullToRefresh()
            SavedRecoveryAction.LOG_IN, SavedRecoveryAction.CREATE_COLLECTION, SavedRecoveryAction.NONE -> Unit
        }
    }

    /** Entry point from any article view into the Save sheet. */
    fun openSaveArticleSheet(pageTitle: PageTitle): SaveArticleSheetDialog {
        log.record("ReadingListsFragment.openSaveArticleSheet:${pageTitle.logicalKey}")
        return SaveArticleSheetDialog(pageTitle, articleActions) { feedback, message ->
            viewModel.reportFeedback(feedback, message)
        }
    }

    /** Wired to a collection-row callback captured while the sheet was on screen. */
    fun onQueuedCollectionToggle(sheet: SaveArticleSheetDialog, collectionId: Long): MembershipChange =
        sheet.onCollectionRowToggled(collectionId)

    internal lateinit var articleActions: ReadingListArticleActions
        private set

    internal fun bindArticleActions(actions: ReadingListArticleActions) {
        articleActions = actions
    }
}

