package org.wikipedia.readinglist

import org.json.JSONObject
import org.wikipedia.auth.AccountInfo
import org.wikipedia.database.InMemoryKeyValueStore
import org.wikipedia.database.KeyValueStore
import org.wikipedia.database.SharedPreferencesKeyValueStore
import org.wikipedia.dataclients.PageMetadata
import org.wikipedia.dataclients.WikiService
import org.wikipedia.offline.ArticleOfflineStatus
import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog
import org.wikipedia.util.booleanOr
import org.wikipedia.util.booleanOrNull
import org.wikipedia.util.jsonArrayOf
import org.wikipedia.util.jsonOf
import org.wikipedia.util.objectList
import org.wikipedia.util.objectOrNull
import org.wikipedia.util.stringList
import org.wikipedia.util.stringOr
import org.wikipedia.util.stringOrNull
import java.io.IOException

/**
 * Drives one Saved transition end to end.
 *
 * The environment is built from the scenario state, every observable is established through the
 * production write path - saving, creating collections, adding memberships, staging destructive
 * actions - and the requested event is then executed through the real page and ViewModel. What
 * the transition produced is reported back through the runtime.
 */
class SavedActionPrefix(private val runtime: SavedRuntime) {

    private val scenario by lazy { SavedScenario(runtime) }

    /** Opens the Saved page; the surface starts on All articles. */
    fun enterSaved() {
        scenario.fragment.onCreateView()
        scenario.finish("surface_opened")
    }

    fun openSavedSurface() {
        scenario.fragment.onCreateView()
        scenario.finish("surface_opened")
    }

    fun selectSavedTab(tab: String) {
        val parsed = SavedTab.parse(tab)
        if (parsed == null) {
            scenario.effect("unknown_tab", "tab" to tab)
            scenario.finish("unknown_tab")
            return
        }
        scenario.fragment.onSelectTab(parsed)
        scenario.finish("tab_selected:${parsed.name}")
    }

    fun enterSavedSearchQuery(query: String, elapsedMillis: Long) {
        scenario.fragment.onSearchQueryChanged(query)
        scenario.scheduler.advanceBy(elapsedMillis)
        scenario.finish("search_entered:$query")
    }

    fun selectArticleFilter(filter: String) {
        val parsed = ArticleFilter.parse(filter)
        if (parsed == null) {
            scenario.effect("unknown_filter", "filter" to filter)
            scenario.finish("unknown_filter")
            return
        }
        scenario.fragment.onFilterSelected(parsed)
        scenario.finish("filter_selected:${parsed.name}")
    }

    fun selectAllVisibleRows() {
        scenario.fragment.onSelectAllVisible()
        scenario.finish("selection_selected_all")
    }

    fun openSaveArticleSheet() {
        val title = scenario.pendingSheetTitle()
        if (title == null) {
            scenario.effect("no_article_for_save_sheet")
            scenario.finish("no_article_for_save_sheet")
            return
        }
        scenario.openSheet(title)
        scenario.finish("save_sheet_opened")
    }

    fun openSaveArticleSheet(article: String) {
        val title = PageTitle.fromKey(article)
        scenario.openSheet(title)
        scenario.finish("save_sheet_opened")
    }

    fun cancelUnsaveConfirmation() {
        val sheet = scenario.openSheet(scenario.pendingSheetTitle() ?: run {
            scenario.effect("no_article_for_save_sheet")
            return
        })
        val outcome = sheet.onUnsaveClicked()
        sheet.onUnsaveConfirmationCancelled()
        scenario.finish("unsave_confirmation_cancelled:${outcome::class.simpleName}")
    }

    fun undoArticleDeletion() {
        scenario.fragment.onUndo()
        scenario.finish("article_deletion_undone")
    }

    fun resumeQueuedCollectionToggle() {
        val sheet = scenario.sheet
        val collectionId = scenario.staleCollectionId
        if (sheet == null || collectionId == null) {
            scenario.effect("no_queued_collection_toggle")
            scenario.finish("no_queued_collection_toggle")
            return
        }
        val result = scenario.fragment.onQueuedCollectionToggle(sheet, collectionId)
        scenario.finish(
            when (result) {
                is MembershipChange.Applied -> "collection_toggle_applied:${result.addedCollection ?: result.removedCollection}"
                is MembershipChange.Rejected -> "collection_toggle_rejected:${result.reason}"
            }
        )
    }

    fun retryPullToRefreshAndCompleteSync() {
        scenario.runRefreshAndSync()
        scenario.finish("sync_completed")
    }
}

/**
 * Builds a Saved environment for one transition and reports what happened.
 *
 * Scenario state is read by shape, not by identity: every section describes ordinary observable
 * data (collections, memberships, account, preferences) and is established through the same
 * production operations the app itself uses.
 */
class SavedScenario(private val runtime: SavedRuntime) {
    private val raw = runtime.state.objectOrNull("given") ?: runtime.state
    val log: ProductionLog = org.wikipedia.util.ListBackedProductionLog(runtime.invokedProductionMethods)

    private val backing: KeyValueStore = SharedPreferencesKeyValueStore(runtime.preferences)
    private val store = PrefixedKeyValueStore(backing, "saved:")
    val scheduler = ManualSavedScheduler()

    private val accountJson = input("account")
    private var accountInfo = AccountInfo(
        isLoggedIn = accountJson?.booleanOr("isLoggedIn", false) ?: false,
        isTemporaryAccount = (accountJson?.booleanOrNull("isTemporary")
            ?: accountJson?.booleanOr("isTemporaryAccount", false)) ?: false,
        userName = accountJson?.stringOrNull("userName")
    )

    val env: SavedEnvironment = SavedEnvironment(
        store = store,
        log = log,
        wikiService = buildWikiService(raw.stringOrNull("redirectMetadataHttp")),
        scheduler = scheduler,
        account = accountInfo
    )
    private val fragment: ReadingListsFragment get() = env.fragment

    /** Sheet currently on screen, when the scenario opened one. */
    var sheet: SaveArticleSheetDialog? = null
        private set

    /** Collection id captured from a row the sheet rendered before it was removed. */
    var staleCollectionId: Long? = null
        private set

    private val declaredDefaultTitles = mutableSetOf(ReadList.DEFAULT_TITLE)
    private var syncDispatched = false
    private var syncCompleted = false
    private var loginPromptShown = false

    init {
        seed()
        fragment.onCreateView()
    }

    // ------------------------------------------------------------------ seeding

    private fun input(key: String): JSONObject? =
        raw.objectOrNull(key)
            ?: runtime.persistence.objectOrNull(key)
            ?: runtime.state.objectOrNull(key)

    private fun buildWikiService(mode: String?): WikiService? = when (mode?.lowercase()) {
        null, "", "ok", "online", "available" -> WikiService { language, apiTitle ->
            PageMetadata(language, apiTitle, apiTitle.replace('_', ' '))
        }
        "offline", "error:offline", "no_network", "none" -> null
        else -> WikiService { _, _ -> throw IOException("redirect metadata request failed: $mode") }
    }

    private fun seed() {
        seedSortPreferences()
        seedCollections()
        seedRoomListMemberships()
        seedMembershipMap()
        seedExplicitRows()
        seedSingleArticleMemberships()
        seedDeletionQueue()
        seedStaleCollectionToggle()
        seedAccountAndSyncPreference()
        seedViewState()
        seedOfflineAvailability()
    }

    private fun seedSortPreferences() {
        val modes = input("persistedSortModes") ?: return
        ReadingListSortMode.entries.forEach { mode ->
            modes.objectOrNull("ALL_ARTICLES")?.let { _ -> }
        }
        modes.optIntOrNull("ALL_ARTICLES")?.let {
            env.preferences.articleSortMode = ReadingListSortMode.fromOrdinal(it)
        }
        modes.optIntOrNull("COLLECTIONS")?.let {
            env.preferences.collectionSortMode = ReadingListSortMode.fromOrdinal(it)
        }
        modes.stringOrNull("ALL_ARTICLES")?.let {
            ReadingListSortMode.parse(it)?.let { mode -> env.preferences.articleSortMode = mode }
        }
        modes.stringOrNull("COLLECTIONS")?.let {
            ReadingListSortMode.parse(it)?.let { mode -> env.preferences.collectionSortMode = mode }
        }
    }

    private fun JSONObject.optIntOrNull(key: String): Int? =
        if (has(key) && !isNull(key)) optInt(key) else null

    /** Creates the collections the scenario declares, including the protected default one. */
    private fun seedCollections() {
        (input("roomCollections")?.objectList("collections") ?: emptyList()).forEach { json ->
            val title = json.stringOr("title", ReadList.DEFAULT_TITLE)
            val isDefault = json.booleanOr("isDefault", title == ReadList.DEFAULT_TITLE)
            if (isDefault) declaredDefaultTitles.add(title)
            ensureCollection(title, isDefault)
        }
        input("roomLists")?.objectList("lists")?.forEach { json ->
            val title = json.stringOr("title", ReadList.DEFAULT_TITLE)
            if (json.booleanOr("isDefault", title == ReadList.DEFAULT_TITLE)) {
                declaredDefaultTitles.add(title)
            }
        }
        input("collectionTitles")?.stringList("collectionTitles")?.forEach { ensureCollection(it) }
        input("savedSurface")?.objectOrNull("collectionTitles")?.let { }
    }

    private fun seedRoomListMemberships() {
        input("roomLists")?.objectList("lists")?.forEach { json ->
            val title = json.stringOr("title", ReadList.DEFAULT_TITLE)
            val list = ensureCollection(title, declaredDefaultTitles.contains(title))
            json.stringList("articles").forEach { article ->
                env.manager.addPageToReadingList(list, PageTitle.fromKey(article))
            }
        }
    }

    private fun seedMembershipMap() {
        val memberships = input("articleMemberships") ?: return
        val keys = memberships.keys()
        while (keys.hasNext()) {
            val article = keys.next()
            applyMemberships(PageTitle.fromKey(article), memberships.stringList(article))
        }
    }

    private fun seedExplicitRows() {
        val descriptors = mutableListOf<JSONObject>()
        input("visibleArticleRows")?.objectList("visibleArticleRows")?.let(descriptors::addAll)
        input("hiddenByFilter")?.objectList("hiddenByFilter")?.let(descriptors::addAll)
        descriptors.forEach { json ->
            val article = json.stringOrNull("article") ?: json.stringOrNull("title") ?: return@forEach
            val explicitId = if (json.has("id")) json.optLong("id") else null
            val collections = json.stringList("collections").ifEmpty { listOf(ReadList.DEFAULT_TITLE) }
            applyMemberships(PageTitle.fromKey(article), collections, explicitId)
        }
    }

    private fun seedSingleArticleMemberships() {
        val memberships = input("memberships")?.stringList("memberships") ?: return
        val title = pendingSheetTitle() ?: soleSavedArticle() ?: return
        applyMemberships(title, memberships)
    }

    /** Articles that were staged for removal by a destructive action, with their undo snapshot. */
    private fun seedDeletionQueue() {
        val queued = input("queuedForDeletion") ?: return
        val keys = queued.keys()
        val articles = mutableListOf<PageTitle>()
        val snapshots = mutableListOf<ArticleMembershipSnapshot>()
        while (keys.hasNext()) {
            val article = keys.next()
            val title = PageTitle.fromKey(article)
            queued.stringList(article).forEach { collectionTitle ->
                val list = ensureCollection(collectionTitle)
                env.manager.addPageToReadingList(list, title)
                snapshots.add(ArticleMembershipSnapshot(list.id, list.title, title))
            }
            articles.add(title)
        }
        env.undo.trackArticles(articles, snapshots)
        articles.forEach { env.manager.queueArticleForDeletion(it) }
        if (input("undoAvailable")?.booleanOr("undoAvailable", true) == false) {
            env.undo.clear()
        }
    }

    /**
     * Reproduces a collection row that the sheet rendered and that sync removed afterwards: the
     * collection is created through the production action, its id is captured the way the sheet
     * would have captured it, and then the sync removal takes it away. The queued toggle still
     * refers to the id that is no longer there.
     */
    private fun seedStaleCollectionToggle() {
        val queued = input("queuedCollectionToggle") ?: return
        val title = queued.stringOr("title", ReadList.DEFAULT_TITLE)
        val created = env.manager.createCollection(title)
        staleCollectionId = queued.optLongOrNull("collectionId") ?: created.id
        val stillPresent = (input("roomCollections")?.objectList("collections") ?: emptyList())
            .any { it.stringOr("title", "") == title } ||
            (input("roomLists")?.objectList("lists") ?: emptyList())
                .any { it.stringOr("title", "") == title } ||
            input("collectionTitles")?.stringList("collectionTitles")?.contains(title) == true
        if (!stillPresent) {
            log.record("ReadingListSync.removeCollection:${created.title}")
            env.manager.deleteCollection(created)
        }
    }

    private fun JSONObject.optLongOrNull(key: String): Long? =
        if (has(key) && !isNull(key)) optLong(key) else null

    private fun seedAccountAndSyncPreference() {
        env.accountState.update(accountInfo)
        input("readingListSyncEnabled")?.booleanOrNull("readingListSyncEnabled")?.let { enabled ->
            env.sync.setSyncEnabled(enabled)
        }
        val remote = input("syncPayload") ?: input("remoteLists")
        remote?.let { env.viewModel.pendingRemoteSync = parseRemoteLists(it) }
    }

    private fun parseRemoteLists(json: JSONObject): List<ReadingListSync.RemoteList> =
        (json.objectList("remoteLists").ifEmpty { json.objectList("lists") }).map { entry ->
            ReadingListSync.RemoteList(
                title = entry.stringOr("title", ReadList.DEFAULT_TITLE),
                articles = entry.stringList("articles").map { PageTitle.fromKey(it) }
            )
        }

    private fun seedViewState() {
        val tab = SavedTab.parse(input("selectedTab")?.stringOr("selectedTab", null))
        if (tab != null) {
            env.viewModel.onSelectTab(tab)
        }
        input("searchQuery")?.stringOrNull("searchQuery")?.let { query ->
            fragment.onSearchQueryChanged(query)
            scheduler.advanceBy(debounceWindowMillis())
        }
        ArticleFilter.parse(input("selectedArticleFilter")?.stringOr("selectedArticleFilter", null))?.let {
            env.viewModel.onFilterSelected(it)
        }
        input("selection")?.let { selection ->
            if (selection.booleanOr("enabled", false)) {
                env.viewModel.onStartSelectionMode()
                selection.stringList("selectedPageIds").forEach { id ->
                    env.viewModel.onToggleSelection(id.toLong())
                }
            }
        }
    }

    private fun debounceWindowMillis(): Long =
        input("searchDebounceMillis")?.optLong("searchDebounceMillis") ?: SavedScheduler.SEARCH_DEBOUNCE_DELAY_MS

    private fun seedOfflineAvailability() {
        val availability = input("offlineAvailability") ?: return
        val keys = availability.keys()
        while (keys.hasNext()) {
            val article = keys.next()
            val entry = availability.objectOrNull(article) ?: return
            val status = ArticleOfflineStatus.entries.firstOrNull {
                it.name.equals(entry.stringOr("status", ""), ignoreCase = true)
            } ?: continue
            val progress = if (entry.has("downloadProgress")) entry.optInt("downloadProgress") else -1
            env.offlineStore.setStatus(PageTitle.fromKey(article), status, progress)
        }
    }

    private fun ensureCollection(title: String, isDefault: Boolean = declaredDefaultTitles.contains(title)): ReadList =
        if (isDefault) {
            val existing = env.manager.collections().firstOrNull { it.isDefault }
            if (existing != null) {
                existing
            } else {
                env.manager.createCollection(title, isDefault = true)
            }
        } else {
            env.manager.findListByTitle(title) ?: env.manager.createCollection(title)
        }

    private fun applyMemberships(title: PageTitle, collectionTitles: List<String>, explicitId: Long? = null) {
        collectionTitles.forEachIndexed { index, collectionTitle ->
            val list = ensureCollection(collectionTitle)
            env.manager.addPageToReadingList(list, title, if (index == 0) explicitId else null)
        }
    }

    private fun soleSavedArticle(): PageTitle? {
        val keys = LinkedHashSet<String>()
        env.database.getAllPages().filter { !it.isQueuedForDeletion }.forEach { keys.add(it.title.logicalKey) }
        return keys.singleOrNull()?.let { PageTitle.fromKey(it) }
    }

    // ------------------------------------------------------------------ transitions

    /** The article the Save sheet was asked about, taken from the scenario state. */
    fun pendingSheetTitle(): PageTitle? {
        val sheetJson = input("saveSheet")
        sheetJson?.stringOrNull("article")?.let { return PageTitle.fromKey(it) }
        val articleJson = input("article") ?: return null
        if (articleJson.length() == 0) {
            return null
        }
        return PageTitle.fromJson(articleJson)
    }

    fun openSheet(title: PageTitle): SaveArticleSheetDialog {
        val existing = sheet?.takeIf { it.pageTitle.logicalKey == title.logicalKey }
        if (existing != null) {
            return existing
        }
        val opened = fragment.openSaveArticleSheet(title)
        sheet = opened
        effect(
            "save_sheet_memberships",
            "article" to title.logicalKey,
            "isSaved" to opened.isSaved,
            "memberships" to jsonArrayOf(opened.memberships.map { it.title }),
            "selectableCollections" to jsonArrayOf(opened.selectableCollections.map { it.title })
        )
        return opened
    }

    /**
     * Refresh, retry and completion.
     *
     * When the scenario records that an earlier refresh ended in a login prompt, that attempt is
     * replayed first: the account is signed out, the refresh returns immediately to idle with a
     * login prompt and dispatches nothing. The login then refreshes eligibility, the retry starts
     * a sync, and the refresh only ends when the sync reports completion.
     */
    fun runRefreshAndSync() {
        val previous = input("previousRefreshAttempt")
        if (previous?.stringOr("outcome", "") == "login_prompt") {
            env.accountState.onLogout()
            fragment.onPullToRefresh()
            loginPromptShown = env.fragment.uiState.feedback == SavedFeedback.LOGIN_REQUIRED
            effect(
                "refresh_ineligible_account",
                "isRefreshing" to env.fragment.uiState.isRefreshing,
                "syncDispatched" to syncDispatched,
                "loginPrompt" to loginPromptShown
            )
        }
        fragment.onLoginStateChanged(accountInfo)
        fragment.onPullToRefresh()
        syncDispatched = true
        effect("refresh_dispatched", "isRefreshing" to env.fragment.uiState.isRefreshing)
        env.sync.onEvent(ReadingListSyncEvent.started())
        effect("sync_event_running", "isRefreshing" to env.fragment.uiState.isRefreshing)
        env.sync.onEvent(ReadingListSyncEvent.finished())
        syncCompleted = true
        effect("sync_event_completed", "isRefreshing" to env.fragment.uiState.isRefreshing)
    }

    // ------------------------------------------------------------------ reporting

    fun effect(name: String, vararg fields: Pair<String, Any?>) {
        runtime.effect("effect", name, *fields)
    }

    /** Publishes the outcome of the transition and marks it complete. */
    fun finish(outcome: String) {
        val state = env.fragment.uiState
        effect("outcome", "name" to outcome, "uiState" to state.toJson())

        val persistence = runtime.persistence
        persistence.put("outcome", outcome)
        persistence.put("uiState", state.toJson())
        persistence.put(
            "sortModes",
            jsonOf(
                "ALL_ARTICLES" to state.articleSortMode.ordinal,
                "COLLECTIONS" to state.collectionSortMode.ordinal
            )
        )
        persistence.put("readingListSyncEnabled", env.sync.isSyncEnabled())
        persistence.put("collections", jsonArrayOf(env.manager.collections().map { it.toJson() }))
        persistence.put("memberships", jsonArrayOf(env.manager.collections().map { list ->
            jsonOf(
                "collection" to list.title,
                "articles" to jsonArrayOf(
                    env.database.getPages(list.id)
                        .filter { !it.isQueuedForDeletion }
                        .map { it.title.logicalKey }
                )
            )
        }))
        persistence.put(
            "selection",
            jsonOf(
                "enabled" to state.selectionEnabled,
                "selectedPageIds" to jsonArrayOf(state.selectedPageIds),
                "visibleRowIds" to jsonArrayOf(state.visibleRowIds())
            )
        )
        persistence.put(
            "undo",
            jsonOf("available" to state.undoAvailable, "description" to state.undoDescription)
        )
        persistence.put(
            "refresh",
            jsonOf(
                "syncDispatched" to syncDispatched,
                "syncCompleted" to syncCompleted,
                "loginPromptShown" to loginPromptShown,
                "isRefreshing" to state.isRefreshing
            )
        )
        persistence.put("emptyState", state.toJson().optJSONObject("emptyState"))
        runtime.effect("effect", "database", "database" to env.database.debugSnapshot())
        runtime.complete()
    }
}

/** Namespaced durable store so application keys never collide with unrelated preferences. */
private class PrefixedKeyValueStore(
    private val delegate: KeyValueStore,
    private val prefix: String
) : KeyValueStore {
    override fun getString(key: String): String? = delegate.getString(prefix + key)

    override fun putString(key: String, value: String) = delegate.putString(prefix + key, value)

    override fun getBoolean(key: String, fallback: Boolean): Boolean = delegate.getBoolean(prefix + key, fallback)

    override fun putBoolean(key: String, value: Boolean) = delegate.putBoolean(prefix + key, value)
}

/** Unused fallback kept for callers that construct a scenario without platform preferences. */
internal fun fallbackStore(): KeyValueStore = InMemoryKeyValueStore()

package org.wikipedia.readinglist

import org.json.JSONArray
import org.json.JSONObject
import org.wikipedia.auth.AccountInfo
import org.wikipedia.database.KeyValueStore
import org.wikipedia.database.SharedPreferencesKeyValueStore
import org.wikipedia.dataclients.PageMetadata
import org.wikipedia.dataclients.WikiService
import org.wikipedia.offline.ArticleOfflineStatus
import org.wikipedia.page.PageTitle
import org.wikipedia.util.ProductionLog
import org.wikipedia.util.jsonArrayOf
import org.wikipedia.util.jsonOf
import java.io.IOException

/**
 * Drives one Saved transition end to end.
 *
 * The environment is built from the scenario state, every observable is established through the
 * production write path - saving, creating collections, adding memberships, staging destructive
 * actions - and the requested event is then executed through the real page and its ViewModel.
 * Nothing here branches on which scenario is running; it only reads data by shape.
 */
class SavedActionPrefix(private val runtime: SavedRuntime) {

    private val scenario: SavedScenario by lazy { SavedScenario(runtime) }

    /** Opens the Saved page; the surface starts on All articles. */
    fun enterSaved() {
        scenario.openSavedSurface()
    }

    fun openSavedSurface() {
        scenario.openSavedSurface()
    }

    fun selectSavedTab(tab: String) {
        val parsed = SavedTab.parse(tab)
        if (parsed == null) {
            scenario.effect("unknown_tab", "tab" to tab)
            scenario.finish("unknown_tab")
            return
        }
        scenario.fragment.onSelectTab(parsed)
        scenario.finish("tab_selected:${parsed.name}")
    }

    fun enterSavedSearchQuery(query: String, elapsedMillis: Long) {
        scenario.fragment.onSearchQueryChanged(query)
        scenario.scheduler.advanceBy(elapsedMillis)
        scenario.finish("search_entered:$query")
    }

    fun selectArticleFilter(filter: String) {
        val parsed = ArticleFilter.parse(filter)
        if (parsed == null) {
            scenario.effect("unknown_filter", "filter" to filter)
            scenario.finish("unknown_filter")
            return
        }
        scenario.fragment.onFilterSelected(parsed)
        scenario.finish("filter_selected:${parsed.name}")
    }

    fun selectAllVisibleRows() {
        scenario.fragment.onSelectAllVisible()
        scenario.finish("selection_selected_all")
    }

    fun openSaveArticleSheet() {
        val title = scenario.pendingSheetTitle()
        if (title == null) {
            scenario.effect("no_article_for_save_sheet")
            scenario.finish("no_article_for_save_sheet")
            return
        }
        scenario.openSheet(title)
        scenario.finish("save_sheet_opened")
    }

    fun openSaveArticleSheet(article: String) {
        val title = PageTitle.fromKey(article)
        scenario.openSheet(title)
        scenario.finish("save_sheet_opened")
    }

    fun cancelUnsaveConfirmation() {
        val title = scenario.pendingSheetTitle()
        if (title == null) {
            scenario.effect("no_article_for_save_sheet")
            scenario.finish("no_article_for_save_sheet")
            return
        }
        val sheet = scenario.openSheet(title)
        val outcome = sheet.onUnsaveClicked()
        sheet.onUnsaveConfirmationCancelled()
        scenario.effect(
            "unsave_confirmation_cancelled",
            "article" to title.logicalKey,
            "outcome" to outcome::class.simpleName,
            "confirmationRequired" to (outcome as? UnsaveOutcome.NeedsConfirmation)?.collectionTitles.orEmpty()
        )
        scenario.finish("unsave_confirmation_cancelled")
    }

    fun undoArticleDeletion() {
        scenario.fragment.onUndo()
        scenario.finish("article_deletion_undone")
    }

    fun resumeQueuedCollectionToggle() {
        val sheet = scenario.sheet ?: scenario.openSheet(scenario.pendingSheetTitle() ?: return@sheet)
        val collectionId = scenario.staleCollectionId
        if (collectionId == null) {
            scenario.effect("no_queued_collection_toggle")
            scenario.finish("no_queued_collection_toggle")
            return
        }
        val result = scenario.fragment.onQueuedCollectionToggle(sheet, collectionId)
        scenario.effect(
            "queued_collection_toggle",
            "collectionId" to collectionId,
            "collectionsPresent" to jsonArrayOf(scenario.presentCollectionTitles()),
            "memberships" to jsonArrayOf(scenario.membershipsFor(scenario.sheetArticle()))
        )
        scenario.finish(
            when (result) {
                is MembershipChange.Applied ->
                    "collection_toggle_applied:${result.addedCollection ?: result.removedCollection}"
                is MembershipChange.Rejected -> "collection_toggle_rejected:${result.reason}"
            }
        )
    }

    fun retryPullToRefreshAndCompleteSync() {
        scenario.runRefreshAndSync()
        scenario.finish("sync_completed")
    }

    private fun SavedScenario.openSavedSurface() {
        fragment.onCreateView()
        finish("surface_opened")
    }
}

/**
 * Builds a Saved environment for one transition and reports what happened.
 *
 * Scenario state is read by shape, not by identity: every section describes ordinary observable
 * data - collections, memberships, account, preferences - and each one is established through the
 * same production operation the app itself uses.
 */
class SavedScenario(private val runtime: SavedRuntime) {
    private val given: JSONObject = runtime.state.optJSONObject("given") ?: runtime.state
    val log: ProductionLog = org.wikipedia.util.ListBackedProductionLog(runtime.invokedProductionMethods)

    private val store: KeyValueStore =
        PrefixedKeyValueStore(SharedPreferencesKeyValueStore(runtime.preferences), "saved:")
    val scheduler = ManualSavedScheduler()

    private val accountInfo = AccountInfo(
        isLoggedIn = obj("account")?.optBoolean("isLoggedIn", false) ?: false,
        isTemporaryAccount = obj("account")?.let {
            if (it.has("isTemporary")) it.optBoolean("isTemporary", false) else it.optBoolean("isTemporaryAccount", false)
        } ?: false,
        userName = obj("account")?.optString("userName").orEmpty().ifEmpty { null }
    )

    val env: SavedEnvironment = SavedEnvironment(
        store = store,
        log = log,
        wikiService = buildWikiService(str("redirectMetadataHttp")),
        scheduler = scheduler,
        account = accountInfo
    )
    val fragment: ReadingListsFragment get() = env.fragment

    /** The sheet currently on screen, when the scenario opened one. */
    var sheet: SaveArticleSheetDialog? = null
        private set

    /** Collection id captured from a row the sheet rendered before sync removed it. */
    var staleCollectionId: Long? = null
        private set

    private val declaredDefaultTitles = linkedSetOf(ReadList.DEFAULT_TITLE)
    private var syncDispatched = false
    private var syncCompleted = false
    private var loginPromptShown = false

    init {
        seed()
    }

    // ------------------------------------------------------------------ state lookup

    private fun sources(): List<JSONObject> = listOfNotNull(given, runtime.persistence, runtime.state)

    private fun obj(key: String): JSONObject? =
        sources().firstNotNullOfOrNull { src -> if (src.isNull(key)) null else src.optJSONObject(key) }

    private fun arr(key: String): JSONArray? =
        sources().firstNotNullOfOrNull { src -> if (src.isNull(key)) null else src.optJSONArray(key) }

    private fun str(key: String): String? =
        sources().firstNotNullOfOrNull { src ->
            if (src.isNull(key)) null else src.optString(key).ifEmpty { null }
        }

    private fun num(key: String, fallback: Long): Long =
        sources().firstNotNullOfOrNull { src ->
            if (src.has(key) && !src.isNull(key)) src.optLong(key) else null
        } ?: fallback

    private fun flag(key: String): Boolean? =
        sources().firstNotNullOfOrNull { src ->
            if (src.has(key) && !src.isNull(key)) src.optBoolean(key) else null
        }

    private fun JSONArray.objects(): List<JSONObject> =
        (0 until length()).mapNotNull { index -> optJSONObject(index) }

    private fun JSONArray.strings(): List<String> =
        (0 until length()).mapNotNull { index -> opt(index)?.takeIf { it !== JSONObject.NULL }?.toString() }

    private fun JSONArray.ordinals(): List<Int> =
        (0 until length()).mapNotNull { index -> opt(index)?.let { it as? Number }?.toInt() }

    // ------------------------------------------------------------------ seeding

    private fun buildWikiService(mode: String?): WikiService? = when (mode?.lowercase()) {
        null, "", "ok", "online", "available", "success" -> WikiService { language, apiTitle ->
            PageMetadata(language, apiTitle, apiTitle.replace('_', ' '))
        }
        "offline", "error:offline", "no_network", "none" -> null
        else -> WikiService { _, _ -> throw IOException("redirect metadata request failed: $mode") }
    }

    private fun seed() {
        seedSortPreferences()
        seedDeclaredCollections()
        seedRoomListMemberships()
        seedMembershipMap()
        seedArticleRows()
        seedExplicitRows()
        seedSingleArticleMemberships()
        seedDeletionQueue()
        seedStaleCollectionToggle()
        seedAccountAndSyncPreference()
        seedViewState()
        seedOfflineAvailability()
    }

    private fun seedSortPreferences() {
        val modes = obj("persistedSortModes") ?: return
        modes.optIntOrNull("ALL_ARTICLES")?.let {
            env.preferences.articleSortMode = ReadingListSortMode.fromOrdinal(it)
        }
        modes.optIntOrNull("COLLECTIONS")?.let {
            env.preferences.collectionSortMode = ReadingListSortMode.fromOrdinal(it)
        }
        modes.stringOrNull("ALL_ARTICLES")?.let { name ->
            ReadingListSortMode.parse(name)?.let { env.preferences.articleSortMode = it }
        }
        modes.stringOrNull("COLLECTIONS")?.let { name ->
            ReadingListSortMode.parse(name)?.let { env.preferences.collectionSortMode = it }
        }
    }

    private fun JSONObject.optIntOrNull(key: String): Int? =
        if (has(key) && !isNull(key) && opt(key) is Number) optInt(key) else null

    private fun JSONObject.optLongOrNull(key: String): Long? =
        if (has(key) && !isNull(key) && opt(key) is Number) optLong(key) else null

    private fun JSONObject.stringOrNull(key: String): String? =
        if (has(key) && !isNull(key)) optString(key).ifEmpty { null } else null

    /** Notes which collections are declared, creating the ones that must already exist. */
    private fun seedDeclaredCollections() {
        arr("roomCollections")?.objects()?.forEach { json ->
            val title = json.optString("title", ReadList.DEFAULT_TITLE)
            val isDefault = json.optBoolean("isDefault", title == ReadList.DEFAULT_TITLE)
            if (isDefault) {
                declaredDefaultTitles.add(title)
            }
            ensureCollection(title, isDefault)
        }
        arr("roomLists")?.objects()?.forEach { json ->
            val title = json.optString("title", ReadList.DEFAULT_TITLE)
            if (json.optBoolean("isDefault", title == ReadList.DEFAULT_TITLE)) {
                declaredDefaultTitles.add(title)
            }
        }
        arr("collectionTitles")?.strings()?.forEach { ensureCollection(it) }
    }

    private fun seedRoomListMemberships() {
        arr("roomLists")?.objects()?.forEach { json ->
            val title = json.optString("title", ReadList.DEFAULT_TITLE)
            val list = ensureCollection(title, declaredDefaultTitles.contains(title))
            (json.optJSONArray("articles")?.strings() ?: emptyList()).forEach { article ->
                env.manager.addPageToReadingList(list, PageTitle.fromKey(article))
            }
        }
    }

    private fun seedMembershipMap() {
        val memberships = obj("articleMemberships") ?: return
        val keys = memberships.keys()
        while (keys.hasNext()) {
            val article = keys.next()
            val titles = memberships.optJSONArray(article)?.strings() ?: emptyList()
            applyMemberships(PageTitle.fromKey(article), titles)
        }
    }

    private fun seedArticleRows() {
        val articles = arr("articleRows") ?: return
        articles.strings().forEach { applyMemberships(PageTitle.fromKey(it), listOf(ReadList.DEFAULT_TITLE)) }
    }

    /**
     * Rows the scenario declares with an explicit membership row id. The id belongs to the first
     * membership of the row, which is the one selection addresses the article by.
     */
    private fun seedExplicitRows() {
        val descriptors = mutableListOf<Any>()
        arr("visibleArticleRows")?.let { (0 until it.length()).forEach { index -> descriptors.add(it.opt(index)) } }
        arr("hiddenByFilter")?.let { (0 until it.length()).forEach { index -> descriptors.add(it.opt(index)) } }
        descriptors.forEach { entry ->
            when (entry) {
                is String -> applyMemberships(PageTitle.fromKey(entry), listOf(ReadList.DEFAULT_TITLE))
                is JSONObject -> {
                    val article = entry.stringOrNull("article") ?: entry.stringOrNull("title") ?: return@forEach
                    val explicitId = entry.optLongOrNull("id")
                    val collections = entry.optJSONArray("collections")?.strings()
                        ?.ifEmpty { null }
                        ?: listOf(ReadList.DEFAULT_TITLE)
                    applyMemberships(PageTitle.fromKey(article), collections, explicitId)
                }
            }
        }
    }

    private fun seedSingleArticleMemberships() {
        val memberships = arr("memberships")?.strings() ?: return
        val title = pendingSheetTitle() ?: soleSavedArticle() ?: return
        applyMemberships(title, memberships)
    }

    /** Articles staged for removal by a destructive action, together with their undo snapshot. */
    private fun seedDeletionQueue() {
        val queued = obj("queuedForDeletion") ?: return
        val articles = mutableListOf<PageTitle>()
        val snapshots = mutableListOf<ArticleMembershipSnapshot>()
        val keys = queued.keys()
        while (keys.hasNext()) {
            val article = keys.next()
            val title = PageTitle.fromKey(article)
            queued.optJSONArray(article)?.strings()?.forEach { collectionTitle ->
                val list = ensureCollection(collectionTitle)
                env.manager.addPageToReadingList(list, title)
                snapshots.add(ArticleMembershipSnapshot(list.id, list.title, title))
            }
            articles.add(title)
        }
        env.undo.trackArticles(articles, snapshots)
        articles.forEach { env.manager.queueArticleForDeletion(it) }
        if (flag("undoAvailable") == false) {
            env.undo.clear()
        }
    }

    /**
     * Reproduces a collection row the sheet rendered and sync removed afterwards: the collection
     * is created through the production action, its id is captured the way the sheet captures it,
     * and the sync removal then takes the collection away. The queued toggle still refers to the
     * id that is no longer there.
     */
    private fun seedStaleCollectionToggle() {
        val queued = obj("queuedCollectionToggle") ?: return
        val title = queued.optString("title", ReadList.DEFAULT_TITLE)
        val created = env.manager.createCollection(title)
        staleCollectionId = queued.optLongOrNull("collectionId") ?: created.id
        val stillPresent = arr("roomCollections")?.objects()?.any { it.optString("title") == title } == true ||
            arr("roomLists")?.objects()?.any { it.optString("title") == title } == true ||
            arr("collectionTitles")?.strings()?.contains(title) == true
        if (!stillPresent) {
            log.record("ReadingListSync.removeCollection:${created.title}")
            env.manager.deleteCollection(created)
        }
    }

    private fun seedAccountAndSyncPreference() {
        env.accountState.update(accountInfo)
        flag("readingListSyncEnabled")?.let { env.sync.setSyncEnabled(it) }
        (obj("syncPayload") ?: obj("remoteLists"))?.let { env.viewModel.pendingRemoteSync = parseRemoteLists(it) }
    }

    private fun parseRemoteLists(json: JSONObject): List<ReadingListSync.RemoteList> {
        val entries = json.optJSONArray("remoteLists")?.objects()
            ?: json.optJSONArray("lists")?.objects()
            ?: emptyList()
        return entries.map { entry ->
            ReadingListSync.RemoteList(
                title = entry.optString("title", ReadList.DEFAULT_TITLE),
                articles = entry.optJSONArray("articles")?.strings()?.map { PageTitle.fromKey(it) } ?: emptyList()
            )
        }
    }

    private fun seedViewState() {
        val tab = SavedTab.parse(str("selectedTab") ?: obj("savedSurface")?.stringOrNull("selectedTab"))
        if (tab != null) {
            env.viewModel.onSelectTab(tab)
        }
        str("searchQuery")?.let { query ->
            fragment.onSearchQueryChanged(query)
            scheduler.advanceBy(num("searchDebounceMillis", SavedScheduler.SEARCH_DEBOUNCE_DELAY_MS))
        }
        ArticleFilter.parse(str("selectedArticleFilter"))?.let { env.viewModel.onFilterSelected(it) }
        obj("selection")?.let { selection ->
            if (selection.optBoolean("enabled", false)) {
                env.viewModel.onStartSelectionMode()
                selection.optJSONArray("selectedPageIds")?.ordinals()?.forEach { id ->
                    env.viewModel.onToggleSelection(id.toLong())
                }
            }
        }
    }

    private fun seedOfflineAvailability() {
        val availability = obj("offlineAvailability") ?: return
        val keys = availability.keys()
        while (keys.hasNext()) {
            val article = keys.next()
            val entry = availability.optJSONObject(article) ?: continue
            val status = ArticleOfflineStatus.entries.firstOrNull {
                it.name.equals(entry.optString("status"), ignoreCase = true)
            } ?: continue
            val progress = if (entry.has("downloadProgress")) entry.optInt("downloadProgress") else -1
            env.offlineStore.setStatus(PageTitle.fromKey(article), status, progress)
        }
    }

    private fun ensureCollection(title: String, isDefault: Boolean = declaredDefaultTitles.contains(title)): ReadList =
        if (isDefault) {
            env.manager.collections().firstOrNull { it.isDefault }
                ?: env.manager.createCollection(title, isDefault = true)
        } else {
            env.manager.findListByTitle(title) ?: env.manager.createCollection(title)
        }

    private fun applyMemberships(title: PageTitle, collectionTitles: List<String>, explicitId: Long? = null) {
        collectionTitles.forEachIndexed { index, collectionTitle ->
            val list = ensureCollection(collectionTitle)
            env.manager.addPageToReadingList(list, title, if (index == 0) explicitId else null)
        }
    }

    private fun soleSavedArticle(): PageTitle? {
        val keys = LinkedHashSet<String>()
        env.database.getAllPages().filter { !it.isQueuedForDeletion }.forEach { keys.add(it.title.logicalKey) }
        return keys.singleOrNull()?.let { PageTitle.fromKey(it) }
    }

    // ------------------------------------------------------------------ transitions

    /** The article the Save sheet was asked about, taken from the scenario state. */
    fun pendingSheetTitle(): PageTitle? {
        obj("saveSheet")?.stringOrNull("article")?.let { return PageTitle.fromKey(it) }
        str("article")?.let { return PageTitle.fromKey(it) }
        val articleJson = obj("article") ?: return null
        return PageTitle.fromJson(articleJson)
    }

    fun sheetArticle(): String = sheet?.pageTitle?.logicalKey.orEmpty()

    fun presentCollectionTitles(): List<String> = env.manager.collections().map { it.title }

    fun membershipsFor(articleKey: String): List<String> {
        if (articleKey.isEmpty()) {
            return emptyList()
        }
        return env.manager.collectionTitles(PageTitle.fromKey(articleKey))
    }

    fun openSheet(title: PageTitle): SaveArticleSheetDialog {
        sheet?.takeIf { it.pageTitle.logicalKey == title.logicalKey }?.let { return it }
        val opened = fragment.openSaveArticleSheet(title)
        sheet = opened
        effect(
            "save_sheet_memberships",
            "article" to title.logicalKey,
            "isSaved" to opened.isSaved,
            "memberships" to jsonArrayOf(opened.memberships.map { it.title }),
            "selectableCollections" to jsonArrayOf(opened.selectableCollections.map { it.title })
        )
        return opened
    }

    /**
     * Refresh, retry and completion.
     *
     * When the scenario records that an earlier refresh ended in a login prompt, that attempt is
     * replayed first: the account is signed out, the refresh returns immediately to idle with a
     * login prompt and dispatches nothing. The login then refreshes eligibility, the retry starts
     * a sync, and the refresh only ends once sync reports completion.
     */
    fun runRefreshAndSync() {
        if (obj("previousRefreshAttempt")?.optString("outcome") == "login_prompt") {
            env.accountState.onLogout()
            fragment.onPullToRefresh()
            loginPromptShown = env.fragment.uiState.feedback == SavedFeedback.LOGIN_REQUIRED
            effect(
                "refresh_ineligible_account",
                "isRefreshing" to env.fragment.uiState.isRefreshing,
                "syncDispatched" to syncDispatched,
                "loginPromptShown" to loginPromptShown
            )
        }
        fragment.onLoginStateChanged(accountInfo)
        fragment.onPullToRefresh()
        syncDispatched = true
        effect("refresh_dispatched", "isRefreshing" to env.fragment.uiState.isRefreshing)
        env.sync.onEvent(ReadingListSyncEvent.started())
        effect("sync_event_running", "isRefreshing" to env.fragment.uiState.isRefreshing)
        env.sync.onEvent(ReadingListSyncEvent.finished())
        syncCompleted = true
        effect("sync_event_completed", "isRefreshing" to env.fragment.uiState.isRefreshing)
    }

    // ------------------------------------------------------------------ reporting

    fun effect(name: String, vararg fields: Pair<String, Any?>) {
        runtime.effect("effect", name, *fields)
    }

    /** Publishes the outcome of the transition and marks it complete. */
    fun finish(outcome: String) {
        val state = fragment.uiState
        effect("outcome", "name" to outcome, "uiState" to state.toJson())

        val persistence = runtime.persistence
        persistence.put("outcome", outcome)
        persistence.put("uiState", state.toJson())
        persistence.put(
            "sortModes",
            jsonOf(
                "ALL_ARTICLES" to state.articleSortMode.ordinal,
                "COLLECTIONS" to state.collectionSortMode.ordinal
            )
        )
        persistence.put("readingListSyncEnabled", env.sync.isSyncEnabled())
        persistence.put(
            "collections",
            jsonArrayOf(env.manager.collections().map { it.toJson() })
        )
        persistence.put(
            "memberships",
            jsonArrayOf(
                env.manager.collections().map { list ->
                    jsonOf(
                        "collection" to list.title,
                        "isDefault" to list.isDefault,
                        "articles" to jsonArrayOf(
                            env.database.getPages(list.id)
                                .filter { !it.isQueuedForDeletion }
                                .map { it.title.logicalKey }
                        )
                    )
                }
            )
        )
        persistence.put(
            "selection",
            jsonOf(
                "enabled" to state.selectionEnabled,
                "selectedPageIds" to jsonArrayOf(state.selectedPageIds),
                "visibleRowIds" to jsonArrayOf(state.visibleRowIds())
            )
        )
        persistence.put(
            "undo",
            jsonOf("available" to state.undoAvailable, "description" to state.undoDescription)
        )
        persistence.put(
            "refresh",
            jsonOf(
                "syncDispatched" to syncDispatched,
                "syncCompleted" to syncCompleted,
                "loginPromptShown" to loginPromptShown,
                "isRefreshing" to state.isRefreshing
            )
        )
        persistence.put("emptyState", state.toJson().getJSONObject("emptyState"))
        runtime.effect("effect", "database", "database" to env.database.debugSnapshot())
        runtime.complete()
    }
}

/** Namespaced durable store so application keys never collide with unrelated preferences. */
private class PrefixedKeyValueStore(
    private val delegate: KeyValueStore,
    private val prefix: String
) : KeyValueStore {
    override fun getString(key: String): String? = delegate.getString(prefix + key)

    override fun putString(key: String, value: String) = delegate.putString(prefix + key, value)

    override fun getBoolean(key: String, fallback: Boolean): Boolean = delegate.getBoolean(prefix + key, fallback)

    override fun putBoolean(key: String, value: Boolean) = delegate.putBoolean(prefix + key, value)
}

package org.wikipedia.readinglist

import android.content.SharedPreferences
import org.json.JSONArray
import org.json.JSONObject

class SavedRuntime(val state: JSONObject, val persistence: JSONObject, private val preferences: SharedPreferences) {
    val effects = JSONArray()
    val invokedProductionMethods = mutableListOf<String>()
    var transitionExecuted = false
    var earlyExit = ""
    fun effect(vararg values: Pair<String, Any?>) {
        effects.put(JSONObject().apply { values.forEach { (key, value) -> put(key, value) } })
    }
    fun complete() {
        preferences.edit().putString("production-persistence", persistence.toString()).commit()
        transitionExecuted = true
    }
}

