package org.wikipedia.readinglist

import android.content.SharedPreferences
import org.json.JSONObject

/** Minimal in-memory [SharedPreferences] for host-side verification of the Saved stack. */
class FakePreferences : SharedPreferences {
    private val values = HashMap<String, Any?>()

    override fun getAll(): MutableMap<String, *> = HashMap(values)

    override fun getString(key: String?, defValue: String?): String? = values[key] as? String ?: defValue

    @Suppress("UNCHECKED_CAST")
    override fun getStringSet(key: String?, defValues: MutableSet<String>?): MutableSet<String>? =
        values[key] as? MutableSet<String> ?: defValues

    override fun getInt(key: String?, defValue: Int): Int = values[key] as? Int ?: defValue

    override fun getLong(key: String?, defValue: Long): Long = values[key] as? Long ?: defValue

    override fun getFloat(key: String?, defValue: Float): Float = values[key] as? Float ?: defValue

    override fun getBoolean(key: String?, defValue: Boolean): Boolean = values[key] as? Boolean ?: defValue

    override fun contains(key: String?): Boolean = values.containsKey(key)

    override fun edit(): SharedPreferences.Editor = FakeEditor()

    override fun registerOnSharedPreferenceChangeListener(
        listener: SharedPreferences.OnSharedPreferenceChangeListener?
    ) = Unit

    override fun unregisterOnSharedPreferenceChangeListener(
        listener: SharedPreferences.OnSharedPreferenceChangeListener?
    ) = Unit

    private inner class FakeEditor : SharedPreferences.Editor {
        private val updates = HashMap<String, Any?>()
        private val removals = HashSet<String>()
        private var clear = false

        override fun putString(key: String, value: String?) = apply { updates[key] = value }
        override fun putStringSet(key: String, values: MutableSet<String>?) = apply { updates[key] = values }
        override fun putInt(key: String, value: Int) = apply { updates[key] = value }
        override fun putLong(key: String, value: Long) = apply { updates[key] = value }
        override fun putFloat(key: String, value: Float) = apply { updates[key] = value }
        override fun putBoolean(key: String, value: Boolean) = apply { updates[key] = value }
        override fun remove(key: String) = apply { removals.add(key) }
        override fun clear() = apply { clear = true }

        override fun commit(): Boolean {
            if (clear) {
                values.clear()
            }
            removals.forEach { values.remove(it) }
            values.putAll(updates)
            return true
        }

        override fun apply() {
            commit()
        }
    }
}

internal fun given(vararg pairs: Pair<String, Any?>): JSONObject {
    val json = JSONObject()
    pairs.forEach { (key, value) -> if (value != null) json.put(key, value) }
    return json
}

internal fun runtimeOf(state: JSONObject): SavedRuntime = SavedRuntime(state, JSONObject(), FakePreferences())

package org.wikipedia.readinglist

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Host-side verification of the public Saved scenarios: each test builds the scenario state,
 * drives the production entry point and inspects the resulting state.
 */
class SavedScenarioTest {

    private fun jsonArray(values: List<String>): JSONArray = JSONArray().apply { values.forEach { put(it) } }

    private fun listObject(vararg pairs: Pair<String, Any?>): JSONObject = given(*pairs)

    private fun stateOf(runtime: SavedRuntime): JSONObject = runtime.persistence

    private fun uiState(runtime: SavedRuntime): JSONObject = runtime.persistence.getJSONObject("uiState")

    private fun articleKeys(runtime: SavedRuntime): List<String> {
        val rows = uiState(runtime).getJSONArray("articleRows")
        return (0 until rows.length()).map { rows.getJSONObject(it).getString("article") }
    }

    private fun collectionTitles(runtime: SavedRuntime): List<String> {
        val rows = uiState(runtime).getJSONArray("collectionRows")
        return (0 until rows.length()).map { rows.getJSONObject(it).getString("title") }
    }

    // ------------------------------------------------------------------ case 1

    @Test
    fun allArticlesDeduplicatesMemberships() {
        val state = given(
            "roomLists" to jsonArray(
                listOf(
                    listObject(
                        "title" to "Saved",
                        "isDefault" to true,
                        "articles" to jsonArray(listOf("en:Ada_Lovelace", "en:Paris"))
                    ),
                    listObject(
                        "title" to "People",
                        "isDefault" to false,
                        "articles" to jsonArray(listOf("en:Ada_Lovelace"))
                    ),
                    listObject(
                        "title" to "Places",
                        "isDefault" to false,
                        "articles" to jsonArray(listOf("fr:Paris"))
                    )
                )
            )
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).openSavedSurface()

        assertTrue(runtime.transitionExecuted)
        assertEquals("", runtime.earlyExit)
        assertEquals(listOf("en:Ada_Lovelace", "en:Paris", "fr:Paris"), articleKeys(runtime))

        val ada = uiState(runtime).getJSONArray("articleRows").getJSONObject(0)
        assertEquals(1, countOccurrences(articleKeys(runtime), "en:Ada_Lovelace"))
        val collections = ada.getJSONArray("collections")
        assertEquals("Saved", collections.getString(0))
        assertEquals("People", collections.getString(1))

        // The fr article is a distinct logical article from the en article.
        assertTrue(articleKeys(runtime).contains("fr:Paris"))
    }

    // ------------------------------------------------------------------ case 2

    @Test
    fun collectionsTabUsesItsOwnSortAndExcludesDefault() {
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "roomLists" to jsonArray(
                listOf(
                    listObject("title" to "Saved", "isDefault" to true),
                    listObject("title" to "Zoo", "isDefault" to false),
                    listObject("title" to "Alpha", "isDefault" to false)
                )
            ),
            "persistedSortModes" to listObject("ALL_ARTICLES" to 1, "COLLECTIONS" to 0)
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).selectSavedTab("COLLECTIONS")

        assertEquals("COLLECTIONS", uiState(runtime).getString("selectedTab"))
        assertEquals(listOf("Alpha", "Zoo"), collectionTitles(runtime))

        // Article sort mode is untouched and still name-descending.
        val modes = stateOf(runtime).getJSONObject("sortModes")
        assertEquals(1, modes.getInt("ALL_ARTICLES"))
        assertEquals(0, modes.getInt("COLLECTIONS"))

        // The default collection is presentation-only filtered: it is still stored.
        val stored = stateOf(runtime).getJSONArray("collections")
        val storedTitles = (0 until stored.length()).map { stored.getJSONObject(it).getString("title") }
        assertTrue(storedTitles.contains("Saved"))
    }

    // ------------------------------------------------------------------ case 3

    @Test
    fun searchIsDebouncedAndScopedToTheActiveTab() {
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "searchQuery" to JSONObject.NULL,
            "searchDebounceMillis" to 150,
            "articleRows" to jsonArray(listOf("en:Cafe", "en:Tea")),
            "collectionTitles" to jsonArray(listOf("Cafe Collection"))
        )
        val runtime = runtimeOf(state)
        val prefix = SavedActionPrefix(runtime)
        // Typed but not yet due: the rows must not be filtered.
        prefix.enterSavedSearchQuery("cafe", 149)
        assertEquals(listOf("en:Cafe", "en:Tea"), articleKeys(runtime))

        val runtime2 = runtimeOf(state.deepCopy())
        SavedActionPrefix(runtime2).enterSavedSearchQuery("cafe", 150)
        assertEquals(listOf("en:Cafe"), articleKeys(runtime2))
        // Search does not mutate membership.
        val collections = stateOf(runtime2).getJSONArray("memberships")
        val saved = (0 until collections.length())
            .map { collections.getJSONObject(it) }
            .first { it.getString("collection") == "Saved" }
        assertEquals(2, saved.getJSONArray("articles").length())
    }

    // ------------------------------------------------------------------ case 4

    @Test
    fun defaultOnlyFilterExcludesAnyArticleInANamedCollection() {
        val memberships = JSONObject()
            .put("en:Default_only", jsonArray(listOf("Saved")))
            .put("en:Default_and_travel", jsonArray(listOf("Saved", "Travel")))
            .put("en:Travel_only", jsonArray(listOf("Travel")))
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "selectedArticleFilter" to "ALL_ARTICLES",
            "articleMemberships" to memberships
        )
        val all = runtimeOf(state.deepCopy())
        SavedActionPrefix(all).openSavedSurface()
        assertEquals(3, articleKeys(all).size)

        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).selectArticleFilter("NOT_IN_COLLECTION")
        assertEquals(listOf("en:Default_only"), articleKeys(runtime))
    }

    // ------------------------------------------------------------------ case 5

    @Test
    fun selectAllTargetsVisibleDeduplicatedRows() {
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "selectedArticleFilter" to "NOT_IN_COLLECTION",
            "visibleArticleRows" to jsonArray(
                listOf(
                    listObject("id" to 11, "article" to "en:Ada_Lovelace"),
                    listObject("id" to 12, "article" to "en:Grace_Hopper")
                )
            ),
            "hiddenByFilter" to jsonArray(
                listOf(
                    listObject(
                        "id" to 13,
                        "article" to "en:Paris",
                        "collections" to jsonArray(listOf("Saved", "Travel"))
                    )
                )
            ),
            "selection" to listObject("enabled" to true, "selectedPageIds" to jsonArray(emptyList()))
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).selectAllVisibleRows()

        val ids = uiState(runtime).getJSONArray("selectedPageIds")
        val selected = (0 until ids.length()).map { ids.getInt(it) }
        assertEquals(listOf(11, 12), selected)
    }

    // ------------------------------------------------------------------ case 6

    @Test
    fun offlineRedirectFailureSavesOriginalIdentity() {
        val state = given(
            "article" to listObject(
                "language" to "en",
                "apiTitle" to "Original_Title",
                "displayTitle" to "Original Title"
            ),
            "memberships" to jsonArray(emptyList()),
            "redirectMetadataHttp" to "error:io",
            "savedSurface" to listObject(
                "selectedTab" to "ALL_ARTICLES",
                "articleRows" to jsonArray(emptyList())
            )
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).openSaveArticleSheet()

        assertEquals(listOf("en:Original_Title"), articleKeys(runtime))
        val saved = (0 until stateOf(runtime).getJSONArray("memberships").length())
            .map { stateOf(runtime).getJSONArray("memberships").getJSONObject(it) }
            .first { it.getString("collection") == "Saved" }
        assertEquals("en:Original_Title", saved.getJSONArray("articles").getString(0))
        assertTrue(
            runtime.invokedProductionMethods.contains("RedirectResolver.resolve:io_failure")
        )
    }

    // ------------------------------------------------------------------ case 7

    @Test
    fun cancellingNamedUnsaveIsANoOp() {
        val state = given(
            "saveSheet" to listObject(
                "article" to "en:Ada_Lovelace",
                "isSaved" to true,
                "pendingConfirmation" to true
            ),
            "memberships" to jsonArray(listOf("Saved", "People"))
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).cancelUnsaveConfirmation()

        assertFalse(runtime.invokedProductionMethods.contains("ReadingListArticleActions.confirmUnsave:en:Ada_Lovelace"))
        val membership = (0 until stateOf(runtime).getJSONArray("memberships").length())
            .map { stateOf(runtime).getJSONArray("memberships").getJSONObject(it) }
            .associate { it.getString("collection") to (0 until it.getJSONArray("articles").length()).map { index -> it.getJSONArray("articles").getString(index) } }
        assertEquals(listOf("en:Ada_Lovelace"), membership["Saved"])
        assertEquals(listOf("en:Ada_Lovelace"), membership["People"])
    }

    // ------------------------------------------------------------------ case 8

    @Test
    fun undoRestoresEveryMembershipOfADeduplicatedArticle() {
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "queuedForDeletion" to JSONObject()
                .put("en:Ada_Lovelace", jsonArray(listOf("Saved", "People"))),
            "visibleArticleRows" to jsonArray(listOf("en:Grace_Hopper")),
            "undoAvailable" to true
        )
        val before = runtimeOf(state.deepCopy())
        SavedActionPrefix(before).openSavedSurface()
        assertEquals(listOf("en:Grace_Hopper"), articleKeys(before))
        assertTrue(stateOf(before).getJSONObject("undo").getBoolean("available"))

        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).undoArticleDeletion()

        assertEquals(listOf("en:Ada_Lovelace", "en:Grace_Hopper"), articleKeys(runtime))
        val ada = uiState(runtime).getJSONArray("articleRows").getJSONObject(0)
        assertEquals("Saved", ada.getJSONArray("collections").getString(0))
        assertEquals("People", ada.getJSONArray("collections").getString(1))
        assertFalse(stateOf(runtime).getJSONObject("undo").getBoolean("available"))
    }

    // ------------------------------------------------------------------ case 9

    @Test
    fun missingCollectionToggleIsANoOp() {
        val state = given(
            "article" to "en:Ada_Lovelace",
            "memberships" to jsonArray(listOf("Saved")),
            "roomCollections" to jsonArray(listOf(listObject("title" to "Saved", "isDefault" to true))),
            "queuedCollectionToggle" to listObject(
                "collectionId" to "observed-created-People-id",
                "title" to "People"
            )
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).resumeQueuedCollectionToggle()

        assertEquals("no_queued_collection_toggle", stateOf(runtime).getString("outcome"))
        assertEquals(listOf("en:Ada_Lovelace"), articleKeys(runtime))
        assertTrue(runtime.invokedProductionMethods.contains("ReadingListManager.toggleCollection:collection_unavailable"))
        val collections = (0 until stateOf(runtime).getJSONArray("collections").length())
            .map { stateOf(runtime).getJSONArray("collections").getJSONObject(it).getString("title") }
        assertEquals(listOf("Saved"), collections)
    }

    // ------------------------------------------------------------------ case 10

    @Test
    fun refreshRetryOnlyEndsWhenSyncReportsCompletion() {
        val state = given(
            "selectedTab" to "ALL_ARTICLES",
            "articleRows" to jsonArray(emptyList()),
            "account" to listObject(
                "isLoggedIn" to true,
                "isTemporary" to false,
                "userName" to "Ada"
            ),
            "previousRefreshAttempt" to listObject("outcome" to "login_prompt", "syncStarted" to false),
            "isRefreshing" to false,
            "readingListSyncEnabled" to false,
            "onboarding" to "SyncReminder",
            "nextSyncCompletion" to "held"
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).retryPullToRefreshAndCompleteSync()

        val refresh = stateOf(runtime).getJSONObject("refresh")
        assertTrue(refresh.getBoolean("loginPromptShown"))
        assertTrue(refresh.getBoolean("syncDispatched"))
        assertTrue(refresh.getBoolean("syncCompleted"))
        assertFalse(refresh.getBoolean("isRefreshing"))
        assertTrue(stateOf(runtime).getBoolean("readingListSyncEnabled"))

        // The signed-out attempt returned to idle without dispatching.
        val ineligible = effectsNamed(runtime).first { it.optString("effect") == "refresh_ineligible_account" }
        assertFalse(ineligible.getBoolean("isRefreshing"))
        assertFalse(ineligible.getBoolean("syncDispatched"))

        val running = effectsNamed(runtime).first { it.optString("effect") == "sync_event_running" }
        assertTrue(running.getBoolean("isRefreshing"))
    }

    // ------------------------------------------------------------------ extras

    @Test
    fun syncProjectionKeepsOneRowPerLogicalArticle() {
        val state = given(
            "account" to listObject("isLoggedIn" to true, "isTemporary" to false, "userName" to "Ada"),
            "articleRows" to jsonArray(emptyList()),
            "syncPayload" to listObject(
                "remoteLists" to jsonArray(
                    listOf(
                        listObject("title" to "Travel", "articles" to jsonArray(listOf("en:Rome"))),
                        listObject("title" to "Reading", "articles" to jsonArray(listOf("en:Rome")))
                    )
                )
            )
        )
        val runtime = runtimeOf(state)
        SavedActionPrefix(runtime).retryPullToRefreshAndCompleteSync()
        assertEquals(listOf("en:Rome"), articleKeys(runtime))
        val rome = uiState(runtime).getJSONArray("articleRows").getJSONObject(0)
        assertEquals(3, rome.getJSONArray("collections").length())
    }

    @Test
    fun emptyStatesAndRecoveryActionsAreDistinct() {
        val empty = runtimeOf(given())
        SavedActionPrefix(empty).openSavedSurface()
        assertEquals("NO_SAVED_ARTICLES", uiState(empty).getJSONObject("emptyState").getString("state"))
        assertEquals("LOG_IN", uiState(empty).getString("recoveryAction"))

        val noResults = runtimeOf(
            given(
                "articleRows" to jsonArray(listOf("en:Tea")),
                "searchQuery" to "nomatch"
            )
        )
        SavedActionPrefix(noResults).openSavedSurface()
        assertEquals("SEARCH_NO_RESULTS", uiState(noResults).getJSONObject("emptyState").getString("state"))
        assertEquals("CLEAR_SEARCH", uiState(noResults).getString("recoveryAction"))

        val noCollections = runtimeOf(given("selectedTab" to "COLLECTIONS"))
        SavedActionPrefix(noCollections).openSavedSurface()
        assertEquals("NO_COLLECTIONS", uiState(noCollections).getJSONObject("emptyState").getString("state"))
        assertEquals("CREATE_COLLECTION", uiState(noCollections).getString("recoveryAction"))
    }

    @Test
    fun switchingTabsChangesMenuActionsAndSortChoices() {
        val state = given(
            "roomLists" to jsonArray(
                listOf(
                    listObject("title" to "Saved", "isDefault" to true, "articles" to jsonArray(listOf("en:Tea"))),
                    listObject("title" to "Ideas", "isDefault" to false, "articles" to jsonArray(listOf("en:Tea")))
                )
            )
        )
        val runtime = runtimeOf(state)
        val prefix = SavedActionPrefix(runtime)
        prefix.openSavedSurface()
        val articleMenu = uiState(runtime).getJSONArray("menuActions").toString()
        assertTrue(articleMenu.contains("FILTER"))
        val scenario = SavedScenario(runtimeOf(state.deepCopy()))
        scenario.fragment.onSelectTab(SavedTab.COLLECTIONS)
        val collectionMenu = scenario.fragment.uiState.toJson().getJSONArray("menuActions").toString()
        assertTrue(collectionMenu.contains("NEW_COLLECTION"))
        assertFalse(collectionMenu.contains("FILTER"))
    }

    @Test
    fun defaultCollectionCannotBeDeleted() {
        val scenario = SavedScenario(runtimeOf(given()))
        val saved = scenario.env.manager.ensureDefaultCollection()
        val result = scenario.env.manager.deleteCollection(saved)
        assertFalse(result.isApplied)
        assertTrue(scenario.env.manager.collections().any { it.isDefault })
    }

    @Test
    fun unsaveOfDefaultOnlyArticleCompletesWithoutConfirmation() {
        val scenario = SavedScenario(runtimeOf(given()))
        val title = org.wikipedia.page.PageTitle.fromKey("en:Solo")
        scenario.env.manager.addPageToReadingList(scenario.env.manager.ensureDefaultCollection(), title)
        val outcome = scenario.env.articleActions.unsave(title)
        assertEquals(UnsaveOutcome.Removed, outcome)
    }

    @Test
    fun collectionLimitBlocksCreationAndLeavesMembershipUnchanged() {
        val scenario = SavedScenario(runtimeOf(given()))
        val title = org.wikipedia.page.PageTitle.fromKey("en:Kept")
        val travel = scenario.env.manager.createCollection("Travel")
        scenario.env.manager.addPageToReadingList(travel, title)
        val rejected = scenario.env.manager.addPageToReadingList(travel, title)
        assertTrue(rejected.isApplied)
        assertTrue(rejected is MembershipChange.Applied && rejected.wasAlreadySaved)
        assertEquals(listOf("Travel"), scenario.env.manager.collectionTitles(title))
    }

    // ------------------------------------------------------------------ helpers

    private fun effectsNamed(runtime: SavedRuntime): List<JSONObject> {
        val array = runtime.effects
        return (0 until array.length()).map { array.getJSONObject(it) }
    }

    private fun countOccurrences(values: List<String>, needle: String): Int = values.count { it == needle }
}

