package org.json

/**
 * Host-side [JSONObject] used only for local verification of the Saved stack.
 *
 * The platform implementation lives in android.jar and is a stub outside a device, so the unit
 * tests supply this equivalent. It is confined to the test source set and is never packaged.
 */
class JSONObject() {

    private val values = LinkedHashMap<String, Any?>()
    private val order = ArrayList<String>()

    constructor(source: String) : this() {
        parse(source)
    }

    constructor(source: Map<*, *>) : this() {
        source.forEach { (key, value) -> put(key.toString(), value) }
    }

    val length: Int get() = order.size

    fun keys(): Iterator<String> = order.toList().iterator()

    fun has(name: String): Boolean = values.containsKey(name)

    fun isNull(name: String): Boolean = !values.containsKey(name) || values[name] === NULL

    fun put(name: String, value: Any?): JSONObject {
        if (!values.containsKey(name)) {
            order.add(name)
        }
        values[name] = value
        return this
    }

    fun remove(name: String): Any? = values.remove(name).also { if (it != null) order.remove(name) }

    fun opt(name: String): Any? = values[name]

