    fun toMap(): Map<String, Any?> = LinkedHashMap(values)

    // ------------------------------------------------------------------ parsing

    private fun parse(source: String) {
        val parser = Parser(source)
        parser.skipWhitespace()
        val parsed = parser.readValue()
        if (parsed is JSONObject) {
            parsed.toMap().forEach { (key, value) -> put(key, value) }
        }
    }

    private class Parser(private val source: String) {
        private var index = 0

        fun skipWhitespace() {
            while (index < source.length && source[index].isWhitespace()) {
                index++
            }
        }

        fun readValue(): Any? {
            skipWhitespace()
            if (index >= source.length) {
                return null
            }
            return when (source[index]) {
                '{' -> readObject()
                '[' -> readArray()
                '"' -> readString()
                else -> readLiteral()
            }
        }

        private fun readObject(): JSONObject {
            expect('{')
            val json = JSONObject()
            skipWhitespace()
            if (peek() == '}') {
                index++
                return json
            }
            while (true) {
                skipWhitespace()
                val key = readString()
                skipWhitespace()
                expect(':')
                json.put(key, readValue())
                skipWhitespace()
                when (peek()) {
                    ',' -> index++
                    '}' -> {
                        index++
                        return json
                    }
                    else -> throw JSONException("Malformed object at $index")
                }
            }
        }

        private fun readArray(): JSONArray {
            expect('[')
            val array = JSONArray()
            skipWhitespace()
            if (peek() == ']') {
                index++
                return array
            }
            while (true) {
                array.put(readValue())
                skipWhitespace()
                when (peek()) {
                    ',' -> index++
                    ']' -> {
                        index++
                        return array
                    }
                    else -> throw JSONException("Malformed array at $index")
                }
            }
        }

        private fun readString(): String {
            expect('"')
            val builder = StringBuilder()
            while (index < source.length) {
                val ch = source[index++]
                when (ch) {
                    '"' -> return builder.toString()
                    '\\' -> {
                        val escaped = source[index++]
                        builder.append(
                            when (escaped) {
                                'n' -> '\n'
                                't' -> '\t'
                                'r' -> '\r'
                                'b' -> '\b'
                                'u' -> source.substring(index, index + 4).toInt(16).toChar().also { index += 4 }
                                else -> escaped
                            }
                        )
                    }
                    else -> builder.append(ch)
                }
            }
            throw JSONException("Unterminated string")
        }

        private fun readLiteral(): Any {
            val start = index
            while (index < source.length && source[index] != ',' && source[index] != '}' && source[index] != ']') {
                index++
            }
            val token = source.substring(start, index).trim()
            return when {
                token == "null" -> NULL
                token == "true" -> true
                token == "false" -> false
                else -> token.toLongOrNull() ?: token.toDoubleOrNull() ?: token
            }
        }

        private fun peek(): Char = if (index < source.length) source[index] else '�'

        private fun expect(ch: Char) {
            skipWhitespace()
            if (index >= source.length || source[index] != ch) {
                throw JSONException("Expected $ch at $index")
            }
            index++
        }
    }

    companion object {
        @JvmField
        val NULL: Any = object {
            override fun equals(other: Any?): Boolean = other === this || other == null
            override fun hashCode(): Int = 0
            override fun toString(): String = "null"
        }

        private fun render(value: Any?): String = when (value) {
            null -> "null"
            NULL -> "null"
            is String -> "\"${value.escape()}\""
            is JSONObject, is JSONArray -> value.toString()
            else -> value.toString()
        }

        private fun String.escape(): String = buildString {
            this@escape.forEach { ch ->
                when (ch) {
                    '"' -> append("\\\"")
                    '\\' -> append("\\\\")
                    '\n' -> append("\\n")
                    '\t' -> append("\\t")
                    '\r' -> append("\\r")
                    else -> append(ch)
                }
            }
        }
    }
}

